window.OMD_CONTENT = {"version":"0.4.0-history-expansion","items":[{"id":"fact-001","category":"Unnützes Wissen","title":"Venustag","text":"Auf der Venus dauert eine vollständige Drehung um die eigene Achse länger als ein Umlauf um die Sonne.","source":"Verifizierte Referenz","sourceUrl":"https://science.nasa.gov/venus/venus-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-002","category":"Unnützes Wissen","title":"Venus rückwärts","text":"Die Venus dreht sich im Vergleich zu den meisten Planeten in entgegengesetzter Richtung.","source":"Verifizierte Referenz","sourceUrl":"https://science.nasa.gov/venus/venus-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-003","category":"Unnützes Wissen","title":"Heißeste Venus","text":"Die Venus ist trotz größerer Sonnenentfernung heißer als Merkur. Ihre dichte Atmosphäre erzeugt einen extremen Treibhauseffekt.","source":"Verifizierte Referenz","sourceUrl":"https://science.nasa.gov/venus/venus-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-004","category":"Unnützes Wissen","title":"Venusdruck","text":"Der Druck an der Venusoberfläche beträgt ungefähr das 93-Fache des irdischen Luftdrucks auf Meereshöhe.","source":"Verifizierte Referenz","sourceUrl":"https://science.nasa.gov/venus/venus-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-005","category":"Unnützes Wissen","title":"Mondrückseite","text":"Menschen sahen die Mondrückseite erstmals 1959 auf Aufnahmen der sowjetischen Sonde Luna 3.","source":"Verifizierte Referenz","sourceUrl":"https://science.nasa.gov/moon/facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-006","category":"Unnützes Wissen","title":"Gebundener Mond","text":"Der Mond rotiert ungefähr so schnell, wie er die Erde umrundet. Deshalb zeigt er uns fast immer dieselbe Seite.","source":"Verifizierte Referenz","sourceUrl":"https://science.nasa.gov/moon/facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-007","category":"Unnützes Wissen","title":"Lebendes Licht","text":"Biolumineszenz ist Licht, das Lebewesen durch chemische Reaktionen selbst erzeugen.","source":"Verifizierte Referenz","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-fact/bioluminescence/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-008","category":"Unnützes Wissen","title":"Leuchtende Tiefsee","text":"Zwischen etwa 200 und 1.000 Metern Meerestiefe sind laut NOAA rund 80 Prozent der dort lebenden Tiere biolumineszent.","source":"Verifizierte Referenz","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-fact/bioluminescence/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-009","category":"Unnützes Wissen","title":"Blaues Tiefseelicht","text":"Biolumineszenz im Meer ist meistens blau, weil blaues Licht im Wasser besonders weit reicht.","source":"Verifizierte Referenz","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-fact/bioluminescence/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-010","category":"Unnützes Wissen","title":"Herz beim Niesen","text":"Das menschliche Herz hört beim Niesen nicht einfach auf zu schlagen.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-011","category":"Unnützes Wissen","title":"Gelenkknacken","text":"Knackgeräusche in Gelenken können unter anderem durch Gasvorgänge und Bewegungen im Gelenk entstehen.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-012","category":"Unnützes Wissen","title":"Stärkster Muskel","text":"Es gibt keinen eindeutig stärksten Muskel, weil Stärke auf verschiedene Arten gemessen werden kann.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-013","category":"Unnützes Wissen","title":"Graue Haare","text":"Graues Haar enthält weniger Pigment; weißes Haar praktisch keines mehr.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-014","category":"Unnützes Wissen","title":"Zombie-Ameisen","text":"Bestimmte Ophiocordyceps-Pilze infizieren Ameisen und verändern deren Verhalten.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-015","category":"Unnützes Wissen","title":"Kraken erkennen Menschen","text":"Oktopusse können lernen, einzelne Menschen voneinander zu unterscheiden.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-016","category":"Unnützes Wissen","title":"Zebras","text":"Zebras lassen sich nicht wie Pferde zuverlässig domestizieren.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-017","category":"Unnützes Wissen","title":"Kamelhöcker","text":"Kamele speichern im Höcker vor allem Fett, nicht Wasser.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-018","category":"Unnützes Wissen","title":"Eisbärenfell","text":"Eisbärenhaare sind weitgehend transparent beziehungsweise farblos und wirken im Verbund weiß.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-019","category":"Unnützes Wissen","title":"Gänse-V","text":"Die V-Formation kann nachfolgenden Gänsen aerodynamische Vorteile verschaffen.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-020","category":"Unnützes Wissen","title":"Fischregen","text":"Kleine Tiere können durch starke Wetterereignisse verfrachtet werden und später an anderer Stelle zu Boden fallen.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-021","category":"Unnützes Wissen","title":"Feuertornado","text":"Unter extremen Brandbedingungen können rotierende Feuersäulen beziehungsweise Feuertornados entstehen.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-022","category":"Unnützes Wissen","title":"Strohhaus","text":"Aus trockenen, fest gepressten Strohballen lassen sich dauerhafte Gebäude errichten.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-023","category":"Unnützes Wissen","title":"Touchscreen","text":"Kapazitive Touchscreens erkennen Berührungen über Veränderungen eines elektrischen Feldes.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-024","category":"Unnützes Wissen","title":"Versteinertes Holz","text":"Bei versteinertem Holz wird organisches Material über lange Zeit durch Mineralien ersetzt.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-025","category":"Unnützes Wissen","title":"Sieben Meere","text":"Für den Ausdruck „die sieben Meere“ gibt es keine universell gültige Liste.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-026","category":"Unnützes Wissen","title":"Black-eyed peas","text":"Black-eyed peas sind botanisch Augenbohnen und keine Erbsen.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-027","category":"Unnützes Wissen","title":"Grapefruit","text":"Der Name Grapefruit wird wahrscheinlich auf das traubenartige Wachstum der Früchte in Gruppen zurückgeführt.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-028","category":"Unnützes Wissen","title":"Kokosnuss","text":"Botanisch ist die Kokosnuss eine Steinfrucht und keine echte Nuss.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-029","category":"Unnützes Wissen","title":"Schokolade","text":"Schokolade schmilzt in der Hand, weil ihr Schmelzbereich unter der menschlichen Körpertemperatur liegt.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-030","category":"Unnützes Wissen","title":"Elementsymbole","text":"Einige Elementsymbole stammen aus älteren, oft lateinischen Namen und passen deshalb nicht zum heutigen Namen.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-031","category":"Unnützes Wissen","title":"Kevlar","text":"Stephanie Kwolek ließ eine ungewöhnliche Polymerlösung trotz Skepsis weiter untersuchen. Daraus entwickelte sich Kevlar.","source":"Verifizierte Referenz","sourceUrl":"https://invention.si.edu/invention-stories/recognize-unusual","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-032","category":"Unnützes Wissen","title":"Scotchgard","text":"Eine versehentlich auf Stoffschuhe gelangte Chemikalie führte zur Entdeckung der wasserabweisenden Eigenschaften hinter Scotchgard.","source":"Verifizierte Referenz","sourceUrl":"https://invention.si.edu/invention-stories/recognize-unusual","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-033","category":"Unnützes Wissen","title":"Post-it","text":"Der Klebstoff hinter Post-it Notes wurde gerade wegen seiner ungewöhnlich schwachen Haftung nützlich.","source":"Verifizierte Referenz","sourceUrl":"https://invention.si.edu/invention-stories/recognize-unusual","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-034","category":"Unnützes Wissen","title":"Mikrowelle","text":"Der Mikrowellenherd entstand aus der Beobachtung einer unerwarteten Erwärmungswirkung bei Arbeiten mit Mikrowellentechnik.","source":"Verifizierte Referenz","sourceUrl":"https://invention.si.edu/invention-stories/recognize-unusual","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-035","category":"Unnützes Wissen","title":"45-Minuten-Krieg","text":"Der Anglo-Sansibar-Krieg von 1896 gilt mit ungefähr 45 Minuten als kürzester Krieg der Geschichte.","source":"Verifizierte Referenz","sourceUrl":"https://www.guinnessworldrecords.com/world-records/65353-shortest-war","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-036","category":"Unnützes Wissen","title":"Ältester Witz","text":"Der älteste von Guinness geführte aufgezeichnete Witz stammt ungefähr aus 1900 v. Chr. und handelt von einem Furz.","source":"Verifizierte Referenz","sourceUrl":"https://www.guinnessworldrecords.com/world-records/491582-oldest-joke","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-037","category":"Unnützes Wissen","title":"Tanzepidemie","text":"1518 ist in Straßburg eine Tanzepidemie historisch dokumentiert. Ihre genaue Ursache ist bis heute nicht abschließend geklärt.","source":"Verifizierte Referenz","sourceUrl":"https://www.history.com/articles/what-was-the-dancing-plague-of-1518","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-038","category":"Unnützes Wissen","title":"Alcatraz","text":"Frank Morris sowie John und Clarence Anglin flohen 1962 aus Alcatraz. Ihr endgültiges Schicksal ist ungeklärt.","source":"Verifizierte Referenz","sourceUrl":"https://www.fbi.gov/history/cases-and-criminals/alcatraz-escape","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-039","category":"Unnützes Wissen","title":"Alcatraz-Versuche","text":"Von 1934 bis 1963 versuchten 36 Männer in 14 Aktionen aus Alcatraz zu fliehen.","source":"Verifizierte Referenz","sourceUrl":"https://www.fbi.gov/history/cases-and-criminals/alcatraz-escape","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-040","category":"Unnützes Wissen","title":"Bienenparagraph","text":"Das deutsche BGB enthält eigene Vorschriften über ausgezogene Bienenschwärme.","source":"Verifizierte Referenz","sourceUrl":"https://www.gesetze-im-internet.de/bgb/__961.html","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-041","category":"Unnützes Wissen","title":"Schatzfund","text":"§ 984 BGB regelt einen Schatzfund grundsätzlich mit hälftigem Eigentum für Finder und Eigentümer der Sache, in der der Schatz verborgen war.","source":"Verifizierte Referenz","sourceUrl":"https://www.gesetze-im-internet.de/bgb/__984.html","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-042","category":"Unnützes Wissen","title":"Bananen","text":"Bananen gelten botanisch als Beeren; Erdbeeren dagegen nicht als echte Beeren.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-043","category":"Unnützes Wissen","title":"Ananas","text":"Eine Ananas entsteht aus vielen einzelnen Blüten, deren Früchte zusammenwachsen.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-044","category":"Unnützes Wissen","title":"Bambus","text":"Bambus gehört botanisch zu den Gräsern.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-045","category":"Unnützes Wissen","title":"Pilze","text":"Pilze bilden ein eigenes Reich und sind keine Pflanzen.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-046","category":"Unnützes Wissen","title":"Korallen","text":"Korallen bestehen aus Kolonien kleiner Tiere, den Polypen.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-047","category":"Unnützes Wissen","title":"Drei Herzen","text":"Oktopusse besitzen drei Herzen.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-048","category":"Unnützes Wissen","title":"Blaues Blut","text":"Viele Kopffüßer transportieren Sauerstoff mit kupferhaltigem Hämocyanin; ihr Blut wirkt dadurch blau.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-049","category":"Unnützes Wissen","title":"Seepferdchen","text":"Bei Seepferdchen trägt das Männchen die sich entwickelnden Eier in einer Bruttasche.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-050","category":"Unnützes Wissen","title":"Wombatwürfel","text":"Wombats sind für würfelförmigen Kot bekannt; die Form entsteht im letzten Darmabschnitt.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-051","category":"Unnützes Wissen","title":"Kolibri","text":"Kolibris können kontrolliert rückwärts fliegen.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-052","category":"Unnützes Wissen","title":"Fledermäuse","text":"Fledermäuse sind nicht blind. Viele Arten kombinieren Sehen mit Echoortung.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-053","category":"Unnützes Wissen","title":"Giraffenhals","text":"Giraffen besitzen wie Menschen normalerweise sieben Halswirbel, nur erheblich längere.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-054","category":"Unnützes Wissen","title":"Schmetterlingsfüße","text":"Viele Schmetterlinge besitzen Geschmacksrezeptoren an den Füßen.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-055","category":"Unnützes Wissen","title":"Bienentanz","text":"Honigbienen können mit dem Schwänzeltanz Richtung und Entfernung einer Futterquelle vermitteln.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-056","category":"Unnützes Wissen","title":"Ameisenatmung","text":"Ameisen besitzen keine Lungen, sondern atmen über ein Tracheensystem.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-057","category":"Unnützes Wissen","title":"Babyknochen","text":"Neugeborene besitzen mehr einzelne Knochen als Erwachsene, weil später viele miteinander verschmelzen.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-058","category":"Unnützes Wissen","title":"Hornhaut","text":"Die Hornhaut des Auges besitzt normalerweise keine Blutgefäße.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-059","category":"Unnützes Wissen","title":"Zungenkarte","text":"Die bekannte Zungenkarte mit streng getrennten Geschmackszonen ist eine irreführende Vereinfachung.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-060","category":"Unnützes Wissen","title":"Gänsehaut","text":"Gänsehaut entsteht durch winzige Muskeln an den Haarfollikeln und ist ein evolutionäres Überbleibsel.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-061","category":"Unnützes Wissen","title":"Jupiter","text":"Jupiter ist der größte Planet unseres Sonnensystems.","source":"Verifizierte Referenz","sourceUrl":"https://science.nasa.gov/jupiter/jupiter-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-062","category":"Unnützes Wissen","title":"Jupitertag","text":"Ein Tag auf Jupiter dauert nur knapp zehn Stunden.","source":"Verifizierte Referenz","sourceUrl":"https://science.nasa.gov/jupiter/jupiter-facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-063","category":"Unnützes Wissen","title":"Uranus","text":"Uranus besitzt eine extrem gekippte Rotationsachse und wirkt, als rolle er auf seiner Umlaufbahn.","source":"Verifizierte Referenz","sourceUrl":"https://science.nasa.gov/uranus/facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-064","category":"Unnützes Wissen","title":"Olympus Mons","text":"Olympus Mons auf dem Mars ist der größte bekannte Vulkan des Sonnensystems.","source":"Verifizierte Referenz","sourceUrl":"https://science.nasa.gov/mars/facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-065","category":"Unnützes Wissen","title":"Sonnenlicht","text":"Sonnenlicht braucht im Mittel etwas mehr als acht Minuten bis zur Erde.","source":"Verifizierte Referenz","sourceUrl":"https://science.nasa.gov/sun/facts/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-066","category":"Unnützes Wissen","title":"Sterne Vergangenheit","text":"Wegen der endlichen Lichtgeschwindigkeit sehen wir entfernte Sterne so, wie sie in der Vergangenheit aussahen.","source":"Verifizierte Referenz","sourceUrl":"https://science.nasa.gov/universe/stars/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-067","category":"Unnützes Wissen","title":"Schall im Vakuum","text":"Im idealen Vakuum kann sich Schall nicht ausbreiten, weil Teilchen zur Weitergabe der Schwingung fehlen.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-068","category":"Unnützes Wissen","title":"Eis schwimmt","text":"Wasser wird beim Gefrieren weniger dicht. Deshalb schwimmt Eis auf flüssigem Wasser.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-069","category":"Unnützes Wissen","title":"Wikingerhörner","text":"Für gehörnte Wikingerhelme im normalen Kampf gibt es keine belastbaren archäologischen Belege.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-070","category":"Unnützes Wissen","title":"Vanille","text":"Echte Vanille wird aus den Früchten bestimmter Orchideenarten gewonnen.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-071","category":"Unnützes Wissen","title":"Safran","text":"Safran besteht aus den getrockneten Narben einer Krokusart.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-072","category":"Unnützes Wissen","title":"Gefrierbrand","text":"Gefrierbrand ist im Kern Feuchtigkeitsverlust gefrorener Lebensmittel, kein tatsächlicher Brand.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-073","category":"Unnützes Wissen","title":"Zwiebeln","text":"Beim Zwiebelschneiden entstehen flüchtige Reizstoffe, die die Augen zum Tränen bringen.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-074","category":"Unnützes Wissen","title":"GPS","text":"GPS muss relativistische Effekte auf Satellitenuhren berücksichtigen, sonst würden Positionsfehler anwachsen.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-075","category":"Unnützes Wissen","title":"Fresnel","text":"Fresnel-Linsen ermöglichen Leuchttürmen eine starke Bündelung des Lichts.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-076","category":"Unnützes Wissen","title":"Donner","text":"Blitze erhitzen Luft extrem schnell; ihre schlagartige Ausdehnung erzeugt die Druckwelle des Donners.","source":"Verifizierte Referenz","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"kelly-001","category":"Kelly Memory","title":"Westfalenhalle auf Risiko","text":"1994 mietete die Kelly Family die Dortmunder Westfalenhalle auf eigenes Risiko. Am 15. Mai war sie mit rund 17.000 Menschen ausverkauft.","source":"KellyFamilySite","sourceUrl":"https://kellyfamilysite.de/","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-002","category":"Kelly Memory","title":"Songs vor Album","text":"„An Angel“, „First Time“ und „Why Why Why“ wurden in der Westfalenhalle 1994 bereits live gespielt, bevor „Over The Hump“ erschien.","source":"KellyFamilySite","sourceUrl":"https://kellyfamilysite.de/","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-003","category":"Kelly Memory","title":"32 Songs","text":"Die Setlist des Westfalenhallen-Konzerts 1994 umfasste 32 Songs.","source":"KellyFamilySite","sourceUrl":"https://kellyfamilysite.de/","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-004","category":"Kelly Memory","title":"Dan Kelly","text":"Beim Konzert 1994 kam Dan Kelly bei „Take My Hand“ auf die Bühne und trat nach seinem Schlaganfall erstmals seit Jahren wieder mit seinen Kindern auf.","source":"KellyFamilySite","sourceUrl":"https://kellyfamilysite.de/","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-005","category":"Kelly Memory","title":"Cliffs of Moher","text":"Fotos für „Over The Hump“ entstanden 1994 an den Cliffs of Moher an Irlands Westküste.","source":"KellyFamilySite","sourceUrl":"https://kellyfamilysite.de/biographie/biographie.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-006","category":"Kelly Memory","title":"Kölner Studio","text":"„Over The Hump“ wurde im Sound Studio N in Köln aufgenommen.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/over_the_hump.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-007","category":"Kelly Memory","title":"Produktion","text":"Hartmut Pfannmüller und Kathy Kelly werden als Produzenten von „Over The Hump“ geführt.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/over_the_hump.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-008","category":"Kelly Memory","title":"Neun im Line-up","text":"Das Album-Line-up umfasste Kathy, John, Patricia, Jimmy, Joey, Barby, Paddy, Maite und Angelo.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/over_the_hump.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-009","category":"Kelly Memory","title":"Track 1","text":"„Why Why Why“ eröffnet „Over The Hump“; die Lead Vocals werden Joey und Paddy zugeschrieben.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/over_the_hump.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-010","category":"Kelly Memory","title":"Track 2","text":"„Father's Nose“ ist Track 2; die Lead Vocals liegen bei Kathy.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/over_the_hump.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-011","category":"Kelly Memory","title":"Track 3","text":"„First Time“ ist Track 3; die Lead Vocals liegen bei Patricia.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/over_the_hump.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-012","category":"Kelly Memory","title":"Durchbruch","text":"„Over The Hump“ wurde 1994 zum entscheidenden kommerziellen Durchbruch der Kelly Family im deutschsprachigen Raum.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/over_the_hump.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-013","category":"Kelly Memory","title":"Straße trotz Halle","text":"Auch nachdem große Hallen gefüllt wurden, spielte die Familie 1994 weiterhin Straßenkonzerte und Straßenfeste.","source":"KellyFamilySite","sourceUrl":"https://kellyfamilysite.de/biographie/biographie.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-014","category":"Kelly Memory","title":"Irland 1994","text":"Anfang 1994 besuchte die Familie Cork und spielte spontan in einer Dubliner Fußgängerzone.","source":"KellyFamilySite","sourceUrl":"https://kellyfamilysite.de/biographie/biographie.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-015","category":"Kelly Memory","title":"Tough Road","text":"„Tough Road Vol. 3 – Backstage“ dokumentiert zentrale Stationen des Jahres 1994, darunter Westfalenhalle, Recording-Session und „An Angel“-Making-of.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/videos/tough_road_vol_3_backstage.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-016","category":"Kelly Memory","title":"30 Jahre später","text":"„Tough Road – Live At Westfalenhalle '94“ erschien zum 30-jährigen Jubiläum erstmals als Live-Album auf CD.","source":"KellyFamilySite","sourceUrl":"https://kellyfamilysite.de/","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-017","category":"Kelly Memory","title":"An Angel verknüpft","text":"Zu „Over The Hump“ gehören als verlinkte Veröffentlichungen unter anderem „An Angel“, „Why Why Why“, „Roses Of Red“ und „First Time“.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/over_the_hump.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-018","category":"Kelly Memory","title":"CD MC LP","text":"„Over The Hump“ ist in den Formaten CD, MC und LP dokumentiert.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/over_the_hump.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-019","category":"Kelly Memory","title":"Executive Producer","text":"Dan Kelly und Mike Ungefehr werden für „Over The Hump“ als Executive Producer geführt.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/over_the_hump.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-020","category":"Kelly Memory","title":"Vor dem Album live","text":"Das große Dortmunder Konzert im Mai 1994 lag zeitlich vor der Veröffentlichung von „Over The Hump“ und macht es zu einem besonders spannenden Zeitdokument.","source":"KellyFamilySite","sourceUrl":"https://kellyfamilysite.de/","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"motivation-001","category":"Motivation","title":"One More Day","text":"Du musst heute nicht die ganze Woche schaffen. Heute reicht heute.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"motivation-002","category":"Motivation","title":"One More Day","text":"Motivation ist unzuverlässig. Gewohnheit taucht wenigstens auch montags auf.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"motivation-003","category":"Motivation","title":"One More Day","text":"Ein schlechter Arbeitstag, den man erledigt hat, ist immer noch erledigt.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"motivation-004","category":"Motivation","title":"One More Day","text":"Fortschritt sieht selten spektakulär aus. Meistens sieht er aus wie: trotzdem gegangen.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"motivation-005","category":"Motivation","title":"One More Day","text":"Manchmal ist Disziplin nur Motivation in Arbeitskleidung.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"motivation-006","category":"Motivation","title":"One More Day","text":"Du brauchst keinen perfekten Tag. Du brauchst nur einen abgeschlossenen.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"motivation-007","category":"Motivation","title":"One More Day","text":"Ein Schritt Richtung Arbeit ist immer auch ein Schritt Richtung Feierabend.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"motivation-008","category":"Motivation","title":"One More Day","text":"Jeder erledigte Arbeitstag ist ein Beweis, dass der nächste machbar ist.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"motivation-009","category":"Motivation","title":"One More Day","text":"Montag ist kein Charaktertest. Er ist nur ein Tag mit sehr schlechtem Marketing.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"motivation-010","category":"Motivation","title":"One More Day","text":"Der innere Schweinehund hat viele Argumente. Er hat nur leider keinen Arbeitsvertrag.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"motivation-011","category":"Motivation","title":"One More Day","text":"Keine Lust zu haben und trotzdem hinzugehen ist eine ziemlich praktische Superkraft.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"motivation-012","category":"Motivation","title":"One More Day","text":"Nicht jeder Tag muss großartig werden. Manchmal reicht: hingegangen, erledigt, nach Hause gekommen.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"motivation-013","category":"Motivation","title":"One More Day","text":"Ein Ziel muss nicht riesig sein. „Heute schaffen“ ist völlig ausreichend.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"motivation-014","category":"Motivation","title":"One More Day","text":"Manchmal gewinnt nicht der motivierteste Mensch, sondern der, der einfach angefangen hat.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"motivation-015","category":"Motivation","title":"One More Day","text":"Der Feierabend fühlt sich besser an, wenn man vorher tatsächlich da war. Ärgerliche Konstruktion, aber offenbar so vorgesehen.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"motivation-016","category":"Motivation","title":"One More Day","text":"Mittwoch ist keine Feier. Aber immerhin ist Montag inzwischen Geschichte.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"motivation-017","category":"Motivation","title":"One More Day","text":"Freitag wird nicht schneller, wenn man Donnerstag böse anschaut.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"motivation-018","category":"Motivation","title":"One More Day","text":"Ein Arbeitstag nach dem anderen. Menschen haben schon kompliziertere Systeme erfolgreich überlebt.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"motivation-019","category":"Motivation","title":"One More Day","text":"Der Weg zur Arbeit ist morgens selten attraktiv. Der Weg zurück hat dagegen ausgezeichnete Bewertungen.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"motivation-020","category":"Motivation","title":"One More Day","text":"One More Day heißt nicht „für immer“. Es heißt genau das: noch diesen einen.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit"]},{"id":"joke-001","category":"Witz","title":"Britisch trocken","text":"Mein Chef sagte, ich solle mehr Eigeninitiative zeigen. Ich bin früher gegangen, bevor er mich darum bitten konnte.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"britisch trocken","sensitive":false,"tags":["Humor","Britisch trocken"]},{"id":"joke-002","category":"Witz","title":"Britisch trocken","text":"Die Besprechung hätte eine E-Mail sein können. Die E-Mail hätte ein Satz sein können. Der Satz hätte unausgesprochen bleiben können.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"britisch trocken","sensitive":false,"tags":["Humor","Britisch trocken"]},{"id":"joke-003","category":"Witz","title":"Britisch trocken","text":"Mein Chef fragte nach meiner langfristigen Perspektive. Ich sagte: Feierabend. Er meinte offenbar etwas anderes.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"britisch trocken","sensitive":false,"tags":["Humor","Britisch trocken"]},{"id":"joke-004","category":"Witz","title":"Britisch trocken","text":"Teamwork bedeutet, dass niemand genau weiß, wer schuld ist, aber alle im Termin sitzen.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"britisch trocken","sensitive":false,"tags":["Humor","Britisch trocken"]},{"id":"joke-005","category":"Witz","title":"Britisch trocken","text":"Wir haben jetzt ein Effizienzprogramm. Die Einführung dazu dauert nur sechs Meetings.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"britisch trocken","sensitive":false,"tags":["Humor","Britisch trocken"]},{"id":"joke-006","category":"Witz","title":"Britisch trocken","text":"Der Drucker meldet Papierstau. Ich respektiere, dass wenigstens einer offen zugibt, heute nicht arbeiten zu wollen.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"britisch trocken","sensitive":false,"tags":["Humor","Britisch trocken"]},{"id":"joke-007","category":"Witz","title":"Britisch trocken","text":"Ich liebe klare Arbeitsanweisungen. Besonders die Sorte, die später mit „So war das nicht gemeint“ endet.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"britisch trocken","sensitive":false,"tags":["Humor","Britisch trocken"]},{"id":"joke-008","category":"Witz","title":"Britisch trocken","text":"Mein Kollege arbeitet angeblich am besten unter Druck. Deshalb beginnen wir grundsätzlich fünf Minuten vor Feierabend.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"britisch trocken","sensitive":false,"tags":["Humor","Britisch trocken"]},{"id":"joke-009","category":"Witz","title":"Norddeutsch","text":"Moin. Mehr Motivation war für heute nicht genehmigt.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"norddeutsch","sensitive":false,"tags":["Humor","Norddeutsch"]},{"id":"joke-010","category":"Witz","title":"Norddeutsch","text":"„Und, wie läuft's?“ – „Vorwärts wär übertrieben, aber rückwärts ist es auch noch nicht.“","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"norddeutsch","sensitive":false,"tags":["Humor","Norddeutsch"]},{"id":"joke-011","category":"Witz","title":"Norddeutsch","text":"Chef: „Kannst du heute länger?“ – „Können schon. Wollen ist organisatorisch schwieriger.“","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"norddeutsch","sensitive":false,"tags":["Humor","Norddeutsch"]},{"id":"joke-012","category":"Witz","title":"Norddeutsch","text":"„Bist du motiviert?“ – „Ich bin da.“ Das muss fürs Erste reichen.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"norddeutsch","sensitive":false,"tags":["Humor","Norddeutsch"]},{"id":"joke-013","category":"Witz","title":"Norddeutsch","text":"Der Kollege sagt, heute werde ein guter Tag. Wir beobachten die Lage weiter.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"norddeutsch","sensitive":false,"tags":["Humor","Norddeutsch"]},{"id":"joke-014","category":"Witz","title":"Norddeutsch","text":"Freitag 13 Uhr. Jetzt bloß keine neuen Ideen mehr. Ideen sind Montagmaterial.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"norddeutsch","sensitive":false,"tags":["Humor","Norddeutsch"]},{"id":"joke-015","category":"Witz","title":"Norddeutsch","text":"Wenn der Chef sagt „nur ganz kurz“, weiß man: Jacke wieder aus.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"norddeutsch","sensitive":false,"tags":["Humor","Norddeutsch"]},{"id":"joke-016","category":"Witz","title":"Arbeit","text":"Der Kaffee fragte, ob ich heute arbeiten möchte. Wir haben beide gelacht.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"]},{"id":"joke-017","category":"Witz","title":"Arbeit","text":"Meine To-do-Liste und ich führen eine Fernbeziehung. Wir wissen voneinander, sehen uns aber selten.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"]},{"id":"joke-018","category":"Witz","title":"Arbeit","text":"Ich wollte heute richtig produktiv sein. Dann kam Arbeit dazwischen.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"]},{"id":"joke-019","category":"Witz","title":"Arbeit","text":"Feierabend ist der Beweis, dass auch schwere Zeiten ein Ende haben.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"]},{"id":"joke-020","category":"Witz","title":"Arbeit","text":"Ich arbeite gern mit Deadlines. Besonders das Geräusch, wenn sie an mir vorbeifliegen.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"]},{"id":"joke-021","category":"Witz","title":"Arbeit","text":"Die Motivation war heute pünktlich. Leider am falschen Arbeitsplatz.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"]},{"id":"joke-022","category":"Witz","title":"Arbeit","text":"Mein Arbeitsplatz ist ergonomisch. Ich kann mich in jeder Position darüber beschweren.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"]},{"id":"joke-023","category":"Witz","title":"Arbeit","text":"Ich habe nichts gegen Überstunden. Ich finde nur, sie sollten jemand anderem passieren.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"]},{"id":"joke-024","category":"Witz","title":"Arbeit","text":"Der Computer fragt, ob ich wirklich herunterfahren möchte. Endlich interessiert sich jemand für meine Gefühle.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"]},{"id":"joke-025","category":"Witz","title":"Arbeit","text":"Montag ist wie ein Softwareupdate: Keiner hat darum gebeten, trotzdem startet es automatisch.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"]},{"id":"joke-026","category":"Witz","title":"Arbeit","text":"Freitag ist mein Lieblingskollege. Kommt regelmäßig und macht die Stimmung besser.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"]},{"id":"joke-027","category":"Witz","title":"Arbeit","text":"Der Chef wollte eine kreative Lösung. Ich habe Urlaub vorgeschlagen.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"]},{"id":"joke-028","category":"Witz","title":"Arbeit","text":"Ich habe heute Multitasking gemacht: gearbeitet, genervt gewesen und an Feierabend gedacht.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"]},{"id":"joke-029","category":"Witz","title":"Arbeit","text":"Man soll seine Komfortzone verlassen. Meine liegt allerdings zuhause.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"]},{"id":"joke-030","category":"Witz","title":"Arbeit","text":"Mein Arbeitsweg dokumentiert täglich, wie weit ein Mensch für Geld fährt.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"]},{"id":"joke-031","category":"Witz","title":"Absurd","text":"Ein Mann geht zum Wahrsager. Der sagt: „Ich sehe, Sie verschwenden gerade Geld.“ Endlich ein Treffer.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"absurd","sensitive":false,"tags":["Humor","Absurd"]},{"id":"joke-032","category":"Witz","title":"Absurd","text":"Mein Kühlschranklicht arbeitet zuverlässiger als ich. Tür auf, sofort Leistung.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"absurd","sensitive":false,"tags":["Humor","Absurd"]},{"id":"joke-033","category":"Witz","title":"Absurd","text":"Ich wollte erwachsen werden. Offenbar war das Abo nicht kündbar.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"absurd","sensitive":false,"tags":["Humor","Absurd"]},{"id":"joke-034","category":"Witz","title":"Absurd","text":"Wenn Zeit Geld ist, müsste Schlaf eigentlich passives Einkommen sein.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"absurd","sensitive":false,"tags":["Humor","Absurd"]},{"id":"joke-035","category":"Witz","title":"Absurd","text":"Mein Handy hat zwei Prozent Akku und trotzdem mehr Lebenswillen als ich montagmorgens.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"absurd","sensitive":false,"tags":["Humor","Absurd"]},{"id":"joke-036","category":"Witz","title":"Absurd","text":"Der Wecker und ich haben eine toxische Beziehung. Er schreit mich morgens an und ich schlage ihn.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"absurd","sensitive":false,"tags":["Humor","Absurd"]},{"id":"joke-037","category":"Witz","title":"Absurd","text":"Ich wollte Ordnung schaffen. Jetzt liegen dieselben Sachen in beschrifteten Kisten.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"absurd","sensitive":false,"tags":["Humor","Absurd"]},{"id":"joke-038","category":"Witz","title":"Beziehung","text":"Meine Partnerin sagte: „Du hörst mir nie zu.“ Seltsamer Einstieg in ein Gespräch.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"beziehung","sensitive":false,"tags":["Humor","Beziehung"]},{"id":"joke-039","category":"Witz","title":"Beziehung","text":"Wir teilen alles in der Beziehung. Sie die Meinung, ich die Schuld.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"beziehung","sensitive":false,"tags":["Humor","Beziehung"]},{"id":"joke-040","category":"Witz","title":"Beziehung","text":"„Was denkst du gerade?“ ist keine Frage. Es ist ein Überraschungstest ohne Lernmaterial.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"beziehung","sensitive":false,"tags":["Humor","Beziehung"]},{"id":"joke-041","category":"Witz","title":"Beziehung","text":"Romantik ist, wenn man fragt: „Soll ich dir auch was aus der Küche mitbringen?“","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"beziehung","sensitive":false,"tags":["Humor","Beziehung"]},{"id":"joke-042","category":"Witz","title":"Beziehung","text":"Eine gute Beziehung besteht aus Liebe, Vertrauen und zwei Meinungen darüber, wie die Spülmaschine eingeräumt wird.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"beziehung","sensitive":false,"tags":["Humor","Beziehung"]},{"id":"joke-043","category":"Witz","title":"Beziehung","text":"Sie sagte, ich solle spontaner sein. Ich habe einen Termin dafür eingetragen.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"beziehung","sensitive":false,"tags":["Humor","Beziehung"]},{"id":"joke-044","category":"Witz","title":"Beziehung","text":"„Mach, was du willst“ ist sprachlich ein Satz und praktisch eine Minenkarte.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"beziehung","sensitive":false,"tags":["Humor","Beziehung"]},{"id":"joke-045","category":"Witz","title":"Arzt","text":"Der Arzt fragte, ob ich regelmäßig Sport mache. Ich sagte: „Ich gehe täglich Risiken aus dem Weg.“","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"arzt","sensitive":false,"tags":["Humor","Arzt"]},{"id":"joke-046","category":"Witz","title":"Arzt","text":"Arzt: „Sie müssen sich mehr bewegen.“ – „Kann ich die Tabletten nicht einfach weiter weg legen?“","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"arzt","sensitive":false,"tags":["Humor","Arzt"]},{"id":"joke-047","category":"Witz","title":"Arzt","text":"Der Arzt sagte: „Sie brauchen Ruhe.“ Ich bat um ein schriftliches Attest für sämtliche Menschen.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"arzt","sensitive":false,"tags":["Humor","Arzt"]},{"id":"joke-048","category":"Witz","title":"Arzt","text":"Beim Arzt stand: „Bitte haben Sie Geduld.“ Schön, wenn die Diagnose schon im Wartezimmer beginnt.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"arzt","sensitive":false,"tags":["Humor","Arzt"]},{"id":"joke-049","category":"Witz","title":"Arzt","text":"Der Arzt meinte, ich solle auf meinen Körper hören. Der sagt seit Stunden „Sofa“. Medizin ist faszinierend.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"arzt","sensitive":false,"tags":["Humor","Arzt"]},{"id":"joke-050","category":"Witz","title":"Arzt","text":"Ich fragte den Arzt nach einer zweiten Meinung. Er sagte: „Gut, Ihre Frisur gefällt mir auch nicht.“","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"arzt","sensitive":false,"tags":["Humor","Arzt"]},{"id":"joke-051","category":"Witz","title":"Schwarz","text":"Der Friedhof ist der beliebteste Ort der Stadt. Die Leute sterben darauf, reinzukommen.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"schwarz","sensitive":true,"tags":["Humor","Schwarz"]},{"id":"joke-052","category":"Witz","title":"Schwarz","text":"Ich habe keine Angst vor dem Tod. Ich finde nur den dauerhaften Offline-Modus etwas übertrieben.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"schwarz","sensitive":true,"tags":["Humor","Schwarz"]},{"id":"joke-053","category":"Witz","title":"Schwarz","text":"Auf meinem Grabstein soll stehen: „Bin gleich zurück.“ Nur um langfristig Erwartungen zu enttäuschen.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"schwarz","sensitive":true,"tags":["Humor","Schwarz"]},{"id":"joke-054","category":"Witz","title":"Schwarz","text":"Wenn ich als Geist zurückkomme, erschrecke ich niemanden. Ich mache nur ständig das Druckerpapier leer.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"schwarz","sensitive":true,"tags":["Humor","Schwarz"]},{"id":"joke-055","category":"Witz","title":"Schwarz","text":"Man lebt nur einmal. Was angesichts mancher Montage auch eine beruhigende Nachricht ist.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"schwarz","sensitive":true,"tags":["Humor","Schwarz"]},{"id":"joke-056","category":"Witz","title":"Schwarz","text":"Mein Plan fürs Alter: so lange leben, bis meine Jugendsünden als historische Quellen gelten.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"schwarz","sensitive":true,"tags":["Humor","Schwarz"]},{"id":"joke-057","category":"Witz","title":"Erwachsen","text":"Erwachsensein ist, wenn man sich über einen neuen Staubsauger freut und danach kurz über sein Leben nachdenkt.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"erwachsen","sensitive":true,"tags":["Humor","Erwachsen"]},{"id":"joke-058","category":"Witz","title":"Erwachsen","text":"Früher blieb ich bis drei Uhr wegen Partys wach. Heute, weil ich falsch gelegen habe und mein Rücken Beschwerde einreicht.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"erwachsen","sensitive":true,"tags":["Humor","Erwachsen"]},{"id":"joke-059","category":"Witz","title":"Erwachsen","text":"Erwachsensein heißt, selbst entscheiden zu dürfen, wann man ins Bett geht, und diese Macht gegen sich einzusetzen.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"erwachsen","sensitive":true,"tags":["Humor","Erwachsen"]},{"id":"joke-060","category":"Witz","title":"Erwachsen","text":"Der spannendste Satz im Erwachsenenleben lautet irgendwann: „Die Maschine ist fertig.“","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"erwachsen","sensitive":true,"tags":["Humor","Erwachsen"]},{"id":"joke-061","category":"Witz","title":"Erwachsen","text":"Früher wollte ich Freiheit. Heute möchte ich einen Termin, bei dem niemand zwischen 8 und 18 Uhr kommt.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"erwachsen","sensitive":true,"tags":["Humor","Erwachsen"]},{"id":"joke-062","category":"Witz","title":"Erwachsen","text":"Mit zunehmendem Alter wird „Wir machen heute nichts“ von einer Drohung zu einem Premiumangebot.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"erwachsen","sensitive":true,"tags":["Humor","Erwachsen"]},{"id":"joke-063","category":"Witz","title":"Derb","text":"Mein Geduldsfaden ist kein Faden mehr. Das ist inzwischen Zahnseide.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"derb","sensitive":true,"tags":["Humor","Derb"]},{"id":"joke-064","category":"Witz","title":"Derb","text":"Manche Menschen sind wie Wolken. Wenn sie verschwinden, wird der Tag sofort schöner.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"derb","sensitive":true,"tags":["Humor","Derb"]},{"id":"joke-065","category":"Witz","title":"Derb","text":"Ich bin nicht nachtragend. Ich habe nur ein hervorragend gepflegtes Archiv.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"derb","sensitive":true,"tags":["Humor","Derb"]},{"id":"joke-066","category":"Witz","title":"Derb","text":"Wenn Dummheit Strom erzeugen würde, könnten manche Meetings das Gebäude autark versorgen.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"derb","sensitive":true,"tags":["Humor","Derb"]},{"id":"joke-067","category":"Witz","title":"Derb","text":"Ich urteile nicht über Menschen. Ich sammle nur sehr schnell Beweismaterial.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"derb","sensitive":true,"tags":["Humor","Derb"]},{"id":"joke-068","category":"Witz","title":"Derb","text":"Ich brauche keine Feinde. Ich habe Gruppen-Chats.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"derb","sensitive":true,"tags":["Humor","Derb"]},{"id":"joke-069","category":"Witz","title":"Derb","text":"Manchmal hilft tief durchatmen. Manchmal hilft Feierabend. Feierabend ist zuverlässiger.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"derb","sensitive":true,"tags":["Humor","Derb"]},{"id":"joke-070","category":"Witz","title":"Derb","text":"Ich bin ein sehr geduldiger Mensch. Nur nicht lange.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"derb","sensitive":true,"tags":["Humor","Derb"]},{"id":"joke-071","category":"Witz","title":"Kurz","text":"Motivation gefunden. War nicht meine.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"kurz","sensitive":false,"tags":["Humor","Kurz"]},{"id":"joke-072","category":"Witz","title":"Kurz","text":"Plan A: funktionieren. Plan B: Kaffee.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"kurz","sensitive":false,"tags":["Humor","Kurz"]},{"id":"joke-073","category":"Witz","title":"Kurz","text":"Ich bin wach. Mehr wurde nicht vereinbart.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"kurz","sensitive":false,"tags":["Humor","Kurz"]},{"id":"joke-074","category":"Witz","title":"Kurz","text":"Heute wird großartig. Quelle: unbestätigt.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"kurz","sensitive":false,"tags":["Humor","Kurz"]},{"id":"joke-075","category":"Witz","title":"Kurz","text":"Der Wille ist da. Er liegt nur ungünstig.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"kurz","sensitive":false,"tags":["Humor","Kurz"]},{"id":"joke-076","category":"Witz","title":"Kurz","text":"Ich kann alles. Nur nicht gleichzeitig und heute.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"kurz","sensitive":false,"tags":["Humor","Kurz"]},{"id":"joke-077","category":"Witz","title":"Kurz","text":"Feierabend lädt … 73 %.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"kurz","sensitive":false,"tags":["Humor","Kurz"]},{"id":"joke-078","category":"Witz","title":"Kurz","text":"Produktivität: Verbindung wird hergestellt.","source":"Originaltext","sourceUrl":null,"verified":true,"tone":"kurz","sensitive":false,"tags":["Humor","Kurz"]},{"id":"fact-077","category":"Unnützes Wissen","title":"Tausendfüßer sind keine Tausendfüßer","text":"Der Name ist unzuverlässig: Die meisten Tausendfüßer haben deutlich weniger als tausend Beine. 2021 wurde allerdings erstmals eine Art mit mehr als 1.000 Beinen beschrieben.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-078","category":"Unnützes Wissen","title":"Hundertfüßer zählen auch nicht sauber","text":"Auch Hundertfüßer haben nicht zwingend genau 100 Beine. Die Zahl variiert je nach Art.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-079","category":"Unnützes Wissen","title":"Motte oder Schmetterling?","text":"Die Unterscheidung zwischen Motten und Tagfaltern ist biologisch weniger sauber, als Alltagssprache vermuten lässt. Typische Merkmale helfen, haben aber Ausnahmen.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-080","category":"Unnützes Wissen","title":"Spinnen kleben nicht überall fest","text":"Spinnen vermeiden, an ihrem eigenen Netz hängen zu bleiben, unter anderem durch die Struktur ihrer Beine und dadurch, dass nicht jeder Faden gleich klebrig ist.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-081","category":"Unnützes Wissen","title":"Armadillos können springen","text":"Neunbinden-Gürteltiere können bei Schreck überraschend hoch senkrecht aufspringen. Im Straßenverkehr ist genau diese Reaktion leider gefährlich.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-082","category":"Unnützes Wissen","title":"Katzen schnurren nicht nur vor Glück","text":"Katzen schnurren nicht ausschließlich, wenn sie zufrieden sind. Auch Stress, Schmerz oder Selbstberuhigung können eine Rolle spielen.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-083","category":"Unnützes Wissen","title":"Mücken wählen tatsächlich aus","text":"Warum manche Menschen häufiger gestochen werden, hängt unter anderem von Körpergeruch, ausgeatmetem Kohlendioxid, Wärme und weiteren chemischen Signalen ab.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-084","category":"Unnützes Wissen","title":"Truthähne haben helles und dunkles Fleisch","text":"Unterschiedliche Muskelarbeit beeinflusst den Myoglobingehalt. Deshalb unterscheiden sich stark beanspruchte und weniger beanspruchte Muskelpartien in Farbe und Geschmack.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-085","category":"Unnützes Wissen","title":"Süßkartoffel ist nicht gleich Yams","text":"Süßkartoffeln und Yams sind botanisch verschiedene Pflanzenfamilien, obwohl die Namen im Handel teilweise durcheinandergehen.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-086","category":"Unnützes Wissen","title":"Fortune Cookies werden gefaltet","text":"Glückskekse werden zunächst flach gebacken. Der Zettel wird eingelegt und der noch warme, biegsame Keks anschließend gefaltet.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-087","category":"Unnützes Wissen","title":"Tiefkühlkost hat einen Namen","text":"Clarence Birdseye gilt als Schlüsselfigur der modernen Tiefkühlkost, weil er Verfahren zur schnellen Gefrierung industriell weiterentwickelte.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-088","category":"Unnützes Wissen","title":"Pfeffer reizt die Nase","text":"Pfeffer kann Niesen auslösen, weil seine Bestandteile empfindliche Nervenenden in der Nasenschleimhaut reizen.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-089","category":"Unnützes Wissen","title":"Grillen als Thermometer","text":"Bei bestimmten Grillenarten hängt die Zirprate von der Temperatur ab. Näherungsformeln können daraus tatsächlich eine Temperatur schätzen.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-090","category":"Unnützes Wissen","title":"Murmeltiere sind schlechte Meteorologen","text":"Der Schatten eines Murmeltiers liefert keine wissenschaftlich verlässliche Vorhersage darüber, ob der Winter sechs Wochen länger dauert.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-091","category":"Unnützes Wissen","title":"Feuerwerk trägt Sterne","text":"Die kleinen pyrotechnischen Pellets, die in Feuerwerkskörpern die sichtbaren Farben erzeugen, werden im Englischen tatsächlich „stars“ genannt.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/chemistry/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-092","category":"Unnützes Wissen","title":"Metalle färben Feuer","text":"Bestimmte Metallverbindungen erzeugen beim Erhitzen charakteristische Farben. Genau dieses Prinzip wird bei farbigem Feuerwerk genutzt.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/chemistry/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-093","category":"Unnützes Wissen","title":"Tiefsee beginnt früh","text":"NOAA definiert den tiefen Ozean typischerweise ab ungefähr 200 Metern, dort wo das Sonnenlicht deutlich schwächer wird.","source":"NOAA","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-fact/deep-ocean/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-094","category":"Unnützes Wissen","title":"Ab 1.000 Metern wird es richtig dunkel","text":"Unterhalb von ungefähr 1.000 Metern erreicht praktisch kein Sonnenlicht mehr den offenen Ozean.","source":"NOAA","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-fact/deep-ocean/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-095","category":"Unnützes Wissen","title":"Tiefsee ist kalt","text":"Die tiefe See hat laut NOAA im Mittel nur ungefähr 4 °C.","source":"NOAA","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-fact/deep-ocean/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-096","category":"Unnützes Wissen","title":"Tiefsee ist Drucksache","text":"In großen Meerestiefen herrscht ein Vielfaches des atmosphärischen Drucks an der Erdoberfläche.","source":"NOAA","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-fact/deep-ocean/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-097","category":"Unnützes Wissen","title":"Fluoreszenz ist kein eigenes Licht","text":"Bei Fluoreszenz wird eingestrahltes Licht aufgenommen und in anderer Farbe wieder abgegeben. Biolumineszenz dagegen entsteht durch eine chemische Reaktion im Organismus.","source":"NOAA","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-fact/living-light/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-098","category":"Unnützes Wissen","title":"Phosphoreszenz leuchtet nach","text":"Phosphoreszierendes Material kann nach dem Ende der Anregung weiterleuchten. Fluoreszenz verschwindet dagegen typischerweise sehr schnell.","source":"NOAA","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-fact/living-light/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-099","category":"Unnützes Wissen","title":"Vampirtintenfisch mit Lichtshow","text":"Vampirtintenfische besitzen Leuchtorgane und können Lichtsignale zur Ablenkung möglicher Angreifer einsetzen.","source":"NOAA","sourceUrl":"https://oceanexplorer.noaa.gov/wp-content/uploads/2025/04/bioluminescence-fact-sheet.pdf","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-100","category":"Unnützes Wissen","title":"Leuchten ohne Hitze","text":"Biolumineszenz erzeugt sichtbares Licht durch chemische Reaktionen und ist wesentlich effizienter als Lichtproduktion über starke Erwärmung.","source":"NOAA","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-fact/living-light/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-101","category":"Unnützes Wissen","title":"Licht zum Verstecken","text":"Einige Meerestiere nutzen Licht nicht nur, um gesehen zu werden, sondern zur Tarnung: Gegenbeleuchtung kann ihre Silhouette von unten abschwächen.","source":"NOAA","sourceUrl":"https://oceanexplorer.noaa.gov/education/bioluminescence/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-102","category":"Unnützes Wissen","title":"Katzen sprechen anders mit uns","text":"Hauskatzen nutzen Miauen besonders intensiv in der Kommunikation mit Menschen; unter erwachsenen Katzen spielt es untereinander eine geringere Rolle.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-103","category":"Unnützes Wissen","title":"Schwarzes und weißes Truthahnfleisch","text":"Brustmuskeln und Beinmuskeln eines Truthahns erfüllen unterschiedliche Aufgaben. Das beeinflusst ihre Zusammensetzung und Farbe.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-104","category":"Unnützes Wissen","title":"Petrified Forest war einmal Wald","text":"Versteinertes Holz bewahrt Strukturen ehemaliger Bäume, obwohl ein großer Teil des ursprünglichen organischen Materials durch Mineralien ersetzt wurde.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/categories/earth-sciences/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-105","category":"Unnützes Wissen","title":"Schnee ist komplizierter als sechs Zacken","text":"Eiskristalle besitzen eine sechszählige Grundsymmetrie, können aber je nach Temperatur und Feuchtigkeit sehr unterschiedliche Formen entwickeln.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/browse-all-questions/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-106","category":"Unnützes Wissen","title":"Schokolade schmilzt absichtlich günstig","text":"Dass Schokolade nahe der Körpertemperatur schmilzt, trägt wesentlich zu ihrem Mundgefühl bei. In der Hand ist dieselbe Eigenschaft weniger beeindruckend.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/chemistry/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-107","category":"Unnützes Wissen","title":"Natrium heißt Na","text":"Das Elementsymbol Na für Natrium stammt vom lateinischen „natrium“. Ähnliche historische Namensreste erklären weitere scheinbar unpassende Symbole.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/chemistry/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-108","category":"Unnützes Wissen","title":"Gold heißt Au","text":"Das chemische Symbol Au für Gold geht auf das lateinische „aurum“ zurück.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/chemistry/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-109","category":"Unnützes Wissen","title":"Eisen heißt Fe","text":"Das Elementsymbol Fe stammt vom lateinischen „ferrum“.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/chemistry/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-110","category":"Unnützes Wissen","title":"Kalium heißt K","text":"Das K in der Chemie stammt von „kalium“, auch wenn das Element auf Englisch potassium heißt.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/chemistry/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-111","category":"Unnützes Wissen","title":"Gefrierbrand ist meist Qualitätsproblem","text":"Gefrierbrand macht Lebensmittel trocken und verändert Geschmack und Textur. Er ist nicht automatisch ein Zeichen für verdorbene Lebensmittel.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/food-and-nutrition/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-112","category":"Unnützes Wissen","title":"Zwiebeln greifen nicht persönlich an","text":"Das Tränen beim Zwiebelschneiden ist eine chemische Abwehrreaktion der Pflanze, keine persönliche Bewertung deiner Kochkünste.","source":"Library of Congress","sourceUrl":"https://www.loc.gov/everyday-mysteries/food-and-nutrition/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-113","category":"Unnützes Wissen","title":"Tiefsee ohne Photosynthese","text":"Unterhalb der lichtdurchfluteten Zone reicht Sonnenlicht nicht für Photosynthese. Tiefseeökosysteme brauchen deshalb andere Energiequellen oder organisches Material von oben.","source":"NOAA","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-fact/deep-ocean/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-114","category":"Unnützes Wissen","title":"Biolumineszenz hat mehrere Erfinder","text":"Die Fähigkeit, Licht zu erzeugen, scheint sich im Lauf der Evolution mehrfach unabhängig entwickelt zu haben.","source":"NOAA","sourceUrl":"https://oceanexplorer.noaa.gov/ocean-fact/bioluminescence/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-115","category":"Unnützes Wissen","title":"Rot ist in der Tiefsee fast schwarz","text":"Rotes Licht dringt im Meerwasser schlecht in große Tiefen vor. Rote Tiere können deshalb in der Tiefsee besonders dunkel wirken.","source":"NOAA","sourceUrl":"https://oceanexplorer.noaa.gov/education/bioluminescence/","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"fact-116","category":"Unnützes Wissen","title":"Lebendes Licht gibt es von Bakterien bis Haien","text":"Biolumineszente Vertreter finden sich in sehr unterschiedlichen Tier- und Organismengruppen des Meeres.","source":"NOAA","sourceUrl":"https://oceanservice.noaa.gov/facts/biolum.html","verified":true,"tone":"curious","sensitive":false,"tags":["Wissen"]},{"id":"kelly-021","category":"Kelly Deep Cut","title":"Almost Heaven erschien 1996","text":"„Almost Heaven“ erschien erstmals am 25. Oktober 1996 und war als CD, MC und LP erhältlich.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/almost_heaven.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-022","category":"Kelly Deep Cut","title":"Zwei Studios für Almost Heaven","text":"„Almost Heaven“ wurde bei Capri Digital in Italien und im Sound Studio N in Köln aufgenommen.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/almost_heaven.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-023","category":"Kelly Deep Cut","title":"Produzenten-Duo","text":"Paddy Kelly und Kathy Kelly werden als Produzenten von „Almost Heaven“ geführt.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/almost_heaven.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-024","category":"Kelly Deep Cut","title":"Albumauftakt 1996","text":"„When The Boys Come Into Town“ eröffnet „Almost Heaven“; Lead Vocals: John, Maite und Paddy.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/almost_heaven.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-025","category":"Kelly Deep Cut","title":"Every Baby","text":"„Every Baby“ ist Track 2 von „Almost Heaven“ und wird von Maite gesungen.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/almost_heaven.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-026","category":"Kelly Deep Cut","title":"I Can't Help Myself","text":"„I Can't Help Myself“ steht auf „Almost Heaven“ an Position 3; Lead Vocals: Angelo und Paddy.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/almost_heaven.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-027","category":"Kelly Deep Cut","title":"Nanana gehört Jimmy","text":"Auf „Almost Heaven“ werden die Lead Vocals von „Nanana“ Jimmy zugeschrieben.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/almost_heaven.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-028","category":"Kelly Deep Cut","title":"You Belong To Me","text":"Patricia übernimmt die Lead Vocals bei „You Belong To Me“ auf „Almost Heaven“.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/almost_heaven.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-029","category":"Kelly Deep Cut","title":"Staying Alive","text":"Joey singt die Lead Vocals von „Staying Alive“ auf „Almost Heaven“.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/almost_heaven.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-030","category":"Kelly Deep Cut","title":"Come Back To Me","text":"„Come Back To Me“ wird auf „Almost Heaven“ von Kathy gesungen.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/almost_heaven.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-031","category":"Kelly Deep Cut","title":"Alien-Duo","text":"Bei „Fell In Love With An Alien“ werden Paddy und Kathy als Lead Vocals geführt.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/almost_heaven.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-032","category":"Kelly Deep Cut","title":"Vier Stimmen bei Hey Diddle Diddle","text":"„Hey Diddle Diddle“ führt Paddy, Maite, Angelo und Barby gemeinsam als Lead Vocals.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/almost_heaven.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-033","category":"Kelly Deep Cut","title":"Like A Queen","text":"Barby übernimmt die Lead Vocals bei „Like A Queen“.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/almost_heaven.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-034","category":"Kelly Deep Cut","title":"Stars Fall From Heaven","text":"Patricia und Maite teilen sich die Lead Vocals bei „Stars Fall From Heaven“.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/almost_heaven.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-035","category":"Kelly Deep Cut","title":"Thunder","text":"Jimmy singt „Thunder“ auf „Almost Heaven“.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/almost_heaven.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-036","category":"Kelly Deep Cut","title":"Calling Heaven","text":"Paddy übernimmt die Lead Vocals bei „Calling Heaven“.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/almost_heaven.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-037","category":"Kelly Deep Cut","title":"Albumabschluss","text":"„Nothing Like Home“ schließt „Almost Heaven“ ab; Lead Vocals: Kathy.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/almost_heaven.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-038","category":"Kelly Memory","title":"Erste Almost-Heaven-Single","text":"„I Can't Help Myself“ erschien in Deutschland am 18. Juli 1996 als Single, noch vor dem Album.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/singles/i_cant_help_myself.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-039","category":"Kelly Deep Cut","title":"Look Up My File als Bonus","text":"Auf der Single „I Can't Help Myself“ befand sich der zuvor unveröffentlichte Bonus-Track „Look Up My File“ mit Paddy als Lead Vocal.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/singles/i_cant_help_myself.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-040","category":"Kelly Memory","title":"Every Baby Single","text":"„Every Baby“ erschien am 21. November 1996 als Single.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/singles/every_baby.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-041","category":"Kelly Deep Cut","title":"Fat Man Bonus-Track","text":"Die „Every Baby“-Single enthielt den zuvor unveröffentlichten Bonus-Track „Fat Man“ mit Paddy, Kathy und Angelo.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/singles/every_baby.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-042","category":"Kelly Memory","title":"Alien am Valentinstag","text":"„Fell In Love With An Alien“ erschien am 14. Februar 1997 als Single. Valentinstag war dafür zumindest thematisch nicht die unpassendste Wahl.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/singles/fell_in_love_with_an_alien.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-043","category":"Kelly Deep Cut","title":"Never Gonna Break Me Down","text":"Die „Fell In Love With An Alien“-Single enthielt „Never Gonna Break Me Down“ als zuvor unveröffentlichten Bonus-Track mit Joey und Paddy.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/singles/fell_in_love_with_an_alien.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-044","category":"Kelly Memory","title":"Nanana Single","text":"„Nanana“ erschien am 23. Mai 1997 als Single.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/singles/nanana.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-045","category":"Kelly Deep Cut","title":"I'm So Happy","text":"Auf der „Nanana“-Single findet sich „I'm So Happy“ mit Angelo als Lead Vocal als zuvor unveröffentlichter Bonus-Track.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/singles/nanana.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-046","category":"Kelly Memory","title":"Because It's Love","text":"„Because It's Love“ erschien am 29. August 1997 als Single und ist mit „Growin' Up“ verknüpft.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/singles/because_its_love.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-047","category":"Kelly Deep Cut","title":"I'll Send You A Letter","text":"Die 3-Track-Version von „Because It's Love“ enthält „I'll Send You A Letter“ mit Paddy und Maite.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/singles/because_its_love.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-048","category":"Kelly Memory","title":"One More Song Single","text":"„One More Song“ erschien am 29. Januar 1998 als Single und ist mit „Growin' Up“ verknüpft.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/singles/one_more_song.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-049","category":"Kelly Deep Cut","title":"Leave It To The Spirits","text":"Die 3-Track-Version von „One More Song“ enthält „Leave It To The Spirits“ mit Barby und Jimmy.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/singles/one_more_song.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-050","category":"Kelly Memory","title":"From Their Hearts","text":"„From Their Hearts“ erschien am 2. November 1998 als Studioalbum.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/from_their_hearts.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-051","category":"Kelly Deep Cut","title":"Drei Produzenten","text":"Paddy, Kathy und Angelo werden als Produzenten von „From Their Hearts“ geführt.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/from_their_hearts.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-052","category":"Kelly Memory","title":"Irland und Frankreich","text":"„From Their Hearts“ wurde mit dem Blue Moon Mobile Recording Unit in Cork sowie im Studio Miraval in Correns, Frankreich, aufgenommen.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/from_their_hearts.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-053","category":"Kelly Deep Cut","title":"Sean als Special Guest","text":"Bei „From Their Hearts“ wird Sean als Special Guest im Line-up geführt.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/from_their_hearts.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-054","category":"Kelly Deep Cut","title":"I Feel Love","text":"„I Feel Love“ eröffnet „From Their Hearts“ mit Paddy, Maite und Angelo als Lead Vocals.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/from_their_hearts.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-055","category":"Kelly Deep Cut","title":"Hooks","text":"„Hooks“ ist Track 2 von „From Their Hearts“ mit Barby und Paddy.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/from_their_hearts.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-056","category":"Kelly Deep Cut","title":"Please Don't Go","text":"Patricia und Jimmy teilen sich die Lead Vocals von „Please Don't Go“.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/from_their_hearts.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-057","category":"Kelly Deep Cut","title":"Maximum","text":"Joey übernimmt die Lead Vocals bei „Maximum“.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/from_their_hearts.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-058","category":"Kelly Deep Cut","title":"Oh It Hurts","text":"Maite singt die Lead Vocals bei „Oh It Hurts“.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/from_their_hearts.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-059","category":"Kelly Deep Cut","title":"Yo Te Quiero","text":"Kathy singt „Yo Te Quiero“ auf „From Their Hearts“.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/from_their_hearts.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-060","category":"Kelly Deep Cut","title":"Dance To The Rock'n'Roll","text":"Paddy, Maite und Sean werden bei „Dance To The Rock'n'Roll“ als Lead Vocals geführt.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/from_their_hearts.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-061","category":"Kelly Deep Cut","title":"Why Don't You Go","text":"Paddy übernimmt „Why Don't You Go“ auf „From Their Hearts“.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/from_their_hearts.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-062","category":"Kelly Deep Cut","title":"You're Losing Me","text":"Kathy singt die Lead Vocals bei „You're Losing Me“.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/from_their_hearts.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-063","category":"Kelly Deep Cut","title":"You Got Me Rockin' Now","text":"Angelo, Paddy und Maite teilen sich die Lead Vocals bei „You Got Me Rockin' Now“.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/from_their_hearts.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-064","category":"Kelly Deep Cut","title":"Hallelujah","text":"Joey übernimmt „Hallelujah“ auf „From Their Hearts“.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/from_their_hearts.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-065","category":"Kelly Deep Cut","title":"Sweetest Angel","text":"Barby singt „Sweetest Angel“ auf „From Their Hearts“.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/from_their_hearts.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-066","category":"Kelly Deep Cut","title":"I Will Be Your Bride","text":"Angelo übernimmt die Lead Vocals bei „I Will Be Your Bride“, dem letzten regulären Track von „From Their Hearts“.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/alben/from_their_hearts.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-067","category":"Kelly Memory","title":"I Really Love You spät als Single","text":"„I Really Love You“ erschien erst am 25. Dezember 1999 als Single, mehr als ein Jahr nach „From Their Hearts“.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/singles/i_really_love_you.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"kelly-068","category":"Kelly Deep Cut","title":"Live-Version auf Single","text":"Eine 3-Track-Version von „I Really Love You“ enthält „Quisiera Ser Un Angel“ als Live-Version mit Paddy und Kathy.","source":"KellyFamilySite","sourceUrl":"https://www.kellyfamilysite.de/discographie/singles/i_really_love_you.html","verified":true,"tone":"fan","sensitive":false,"tags":["Kelly","Deep Cut"]},{"id":"joke-079","category":"Witz","title":"Britisch trocken","text":"Ich habe meinem Chef gesagt, ich brauche mehr Anerkennung. Er nickte und sagte: „Das stimmt.“","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"britisch trocken","sensitive":false,"tags":["Humor","Britisch trocken"]},{"id":"joke-080","category":"Witz","title":"Britisch trocken","text":"Wir suchen keine Schuldigen. Wir möchten nur wissen, wer es war.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"britisch trocken","sensitive":false,"tags":["Humor","Britisch trocken"]},{"id":"joke-081","category":"Witz","title":"Britisch trocken","text":"Das Projekt ist fast fertig. Es fehlen nur noch die Dinge, die funktionieren müssen.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"britisch trocken","sensitive":false,"tags":["Humor","Britisch trocken"]},{"id":"joke-082","category":"Witz","title":"Britisch trocken","text":"Unsere neue Software spart Zeit. Seit der Einführung dokumentieren wir täglich, wie viel.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"britisch trocken","sensitive":false,"tags":["Humor","Britisch trocken"]},{"id":"joke-083","category":"Witz","title":"Britisch trocken","text":"Ich habe einen Verbesserungsvorschlag eingereicht. Jetzt weiß ich, warum das Formular so gut versteckt war.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"britisch trocken","sensitive":false,"tags":["Humor","Britisch trocken"]},{"id":"joke-084","category":"Witz","title":"Britisch trocken","text":"Der Termin beginnt pünktlich um neun. Inhaltlich kommt er gegen halb elf dazu.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"britisch trocken","sensitive":false,"tags":["Humor","Britisch trocken"]},{"id":"joke-085","category":"Witz","title":"Britisch trocken","text":"Wir haben flache Hierarchien. Der Unsinn fällt dadurch schneller nach unten.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"britisch trocken","sensitive":false,"tags":["Humor","Britisch trocken"]},{"id":"joke-086","category":"Witz","title":"Britisch trocken","text":"Der Plan ist absolut realistisch, sofern nichts Reales passiert.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"britisch trocken","sensitive":false,"tags":["Humor","Britisch trocken"]},{"id":"joke-087","category":"Witz","title":"Britisch trocken","text":"Mein Chef liebt offene Kommunikation. Deshalb schließt er vorher die Tür.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"britisch trocken","sensitive":false,"tags":["Humor","Britisch trocken"]},{"id":"joke-088","category":"Witz","title":"Britisch trocken","text":"Das Problem ist gelöst. Wir haben es in „Herausforderung“ umbenannt.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"britisch trocken","sensitive":false,"tags":["Humor","Britisch trocken"]},{"id":"joke-089","category":"Witz","title":"Norddeutsch","text":"„Wie ist die Stimmung?“ – „Anwesend.“","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"norddeutsch","sensitive":false,"tags":["Humor","Norddeutsch"]},{"id":"joke-090","category":"Witz","title":"Norddeutsch","text":"Heute läuft's. Wohin, ist noch offen.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"norddeutsch","sensitive":false,"tags":["Humor","Norddeutsch"]},{"id":"joke-091","category":"Witz","title":"Norddeutsch","text":"„Freust du dich?“ – „Ich beschwer mich nicht.“ Höchste norddeutsche Auszeichnung.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"norddeutsch","sensitive":false,"tags":["Humor","Norddeutsch"]},{"id":"joke-092","category":"Witz","title":"Norddeutsch","text":"Chef sagt, wir müssen flexibel bleiben. Feierabend bleibt vorsichtshalber flexibel nach hinten.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"norddeutsch","sensitive":false,"tags":["Humor","Norddeutsch"]},{"id":"joke-093","category":"Witz","title":"Norddeutsch","text":"Montag. Kannste machen. Musste aber nicht gut finden.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"norddeutsch","sensitive":false,"tags":["Humor","Norddeutsch"]},{"id":"joke-094","category":"Witz","title":"Norddeutsch","text":"„War schlimm?“ – „Ging.“ Das Ereignis kann zwischen leichtem Regen und Weltuntergang gelegen haben.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"norddeutsch","sensitive":false,"tags":["Humor","Norddeutsch"]},{"id":"joke-095","category":"Witz","title":"Norddeutsch","text":"Kollege: „Noch Kaffee?“ – „Jo.“ Damit ist das Motivationsseminar beendet.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"norddeutsch","sensitive":false,"tags":["Humor","Norddeutsch"]},{"id":"joke-096","category":"Witz","title":"Norddeutsch","text":"Mittwoch. Nicht schön, aber schon mal kein Montag.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"norddeutsch","sensitive":false,"tags":["Humor","Norddeutsch"]},{"id":"joke-097","category":"Witz","title":"Norddeutsch","text":"Freitag. Jetzt nicht übermütig werden. Erst ausstempeln.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"norddeutsch","sensitive":false,"tags":["Humor","Norddeutsch"]},{"id":"joke-098","category":"Witz","title":"Norddeutsch","text":"„Bis morgen.“ – „Wenn's sein muss.“ Kollegiale Zuneigung, norddeutsche Ausgabe.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"norddeutsch","sensitive":false,"tags":["Humor","Norddeutsch"]},{"id":"joke-099","category":"Witz","title":"Arbeit","text":"Ich habe meinen Arbeitsplatz heute erreicht. Der Rest ist Bonusmaterial.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"]},{"id":"joke-100","category":"Witz","title":"Arbeit","text":"Meine Motivation arbeitet im Schichtmodell. Heute hat sie frei.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"]},{"id":"joke-101","category":"Witz","title":"Arbeit","text":"Ich wollte früher anfangen. Dann fiel mir ein, dass Arbeit trotzdem gleich lang dauert.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"]},{"id":"joke-102","category":"Witz","title":"Arbeit","text":"Der Feierabend ist heute wieder überraschend weit vom Arbeitsbeginn entfernt.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"]},{"id":"joke-103","category":"Witz","title":"Arbeit","text":"Ich brauche keinen Karriereplan. Ich brauche einen Kalender mit mehr Freitagen.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"]},{"id":"joke-104","category":"Witz","title":"Arbeit","text":"Der Chef sagt, jeder sei ersetzbar. Ich warte noch auf die praktische Vorführung.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"]},{"id":"joke-105","category":"Witz","title":"Arbeit","text":"Wenn Erfahrung unbezahlbar ist, müsste mein Konto inzwischen beeindruckender aussehen.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"]},{"id":"joke-106","category":"Witz","title":"Arbeit","text":"Ich bin nicht unmotiviert. Ich arbeite nur sehr energiesparend.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"]},{"id":"joke-107","category":"Witz","title":"Arbeit","text":"Meine Lieblingsaufgabe ist die, die jemand gestern schon erledigt hat.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"]},{"id":"joke-108","category":"Witz","title":"Arbeit","text":"Es gibt Tage, da arbeitet man für Geld. Und Tage, da arbeitet man hauptsächlich für Feierabend.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"]},{"id":"joke-109","category":"Witz","title":"Arbeit","text":"Die Uhr auf Arbeit läuft nicht langsamer. Sie genießt es nur mehr.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"]},{"id":"joke-110","category":"Witz","title":"Arbeit","text":"Ich habe heute einen produktiven Gedanken gehabt. Er war schnell wieder weg.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"]},{"id":"joke-111","category":"Witz","title":"Arbeit","text":"Mein Chef sagte: „Denk mit.“ Seitdem denke ich darüber nach, nach Hause zu gehen.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"]},{"id":"joke-112","category":"Witz","title":"Arbeit","text":"Arbeitsmoral ist, wenn man trotz hervorragender Ausreden auftaucht.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"]},{"id":"joke-113","category":"Witz","title":"Arbeit","text":"Die Maschine läuft. Jetzt bloß keinen Menschen dranlassen.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"]},{"id":"joke-114","category":"Witz","title":"Arbeit","text":"Ich liebe Routine. Besonders den Teil, in dem irgendwann Feierabend ist.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"]},{"id":"joke-115","category":"Witz","title":"Arbeit","text":"Die wichtigste berufliche Fähigkeit ist, beschäftigt auszusehen, während Windows neu startet.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"]},{"id":"joke-116","category":"Witz","title":"Arbeit","text":"Ich wollte heute nichts aufschieben. Das mache ich morgen.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"]},{"id":"joke-117","category":"Witz","title":"Arbeit","text":"Die Arbeit rennt nicht weg. Das ist leider das Problem.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"]},{"id":"joke-118","category":"Witz","title":"Arbeit","text":"Kaffee ist kein Arbeitsmittel. Kaffee ist die Personalabteilung meines Nervensystems.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"arbeit","sensitive":false,"tags":["Humor","Arbeit"]},{"id":"joke-119","category":"Witz","title":"Absurd","text":"Mein Navi sagte „Bitte wenden“. Endlich mal Technik, die meine Lebensentscheidungen kennt.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"absurd","sensitive":false,"tags":["Humor","Absurd"]},{"id":"joke-120","category":"Witz","title":"Absurd","text":"Ich habe versucht, vernünftig zu sein. War nicht kompatibel.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"absurd","sensitive":false,"tags":["Humor","Absurd"]},{"id":"joke-121","category":"Witz","title":"Absurd","text":"Mein Konto und ich haben unterschiedliche Vorstellungen von spontanem Luxus.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"absurd","sensitive":false,"tags":["Humor","Absurd"]},{"id":"joke-122","category":"Witz","title":"Absurd","text":"Ich räume nicht auf. Ich verändere die Suchwahrscheinlichkeit von Gegenständen.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"absurd","sensitive":false,"tags":["Humor","Absurd"]},{"id":"joke-123","category":"Witz","title":"Absurd","text":"Ich habe heute nichts verloren. Ich weiß nur bei mehreren Dingen nicht, wo sie sind.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"absurd","sensitive":false,"tags":["Humor","Absurd"]},{"id":"joke-124","category":"Witz","title":"Absurd","text":"Der Akku meines Staubsaugers hält länger durch als meine Begeisterung fürs Putzen.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"absurd","sensitive":false,"tags":["Humor","Absurd"]},{"id":"joke-125","category":"Witz","title":"Absurd","text":"Ich habe einen Kalender gekauft, damit ich genau weiß, an welchem Datum ich Dinge vergesse.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"absurd","sensitive":false,"tags":["Humor","Absurd"]},{"id":"joke-126","category":"Witz","title":"Absurd","text":"Mein Sofa unterstützt mich in jeder Lebenslage. Beruflich leider nicht.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"absurd","sensitive":false,"tags":["Humor","Absurd"]},{"id":"joke-127","category":"Witz","title":"Absurd","text":"Ich wollte meine Komfortzone verlassen. Draußen war Wetter.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"absurd","sensitive":false,"tags":["Humor","Absurd"]},{"id":"joke-128","category":"Witz","title":"Absurd","text":"Mein Gehirn speichert nachts zuverlässig peinliche Gespräche von 2007, aber keine Passwörter.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"absurd","sensitive":false,"tags":["Humor","Absurd"]},{"id":"joke-129","category":"Witz","title":"Beziehung","text":"Beziehungen sind Teamarbeit. Einer fragt „Wo ist das?“ und der andere findet es an exakt der beschriebenen Stelle.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"beziehung","sensitive":false,"tags":["Humor","Beziehung"]},{"id":"joke-130","category":"Witz","title":"Beziehung","text":"Wir haben beschlossen, mehr miteinander zu reden. Seitdem diskutieren wir ausführlicher.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"beziehung","sensitive":false,"tags":["Humor","Beziehung"]},{"id":"joke-131","category":"Witz","title":"Beziehung","text":"Liebe ist, wenn man die Decke teilt und morgens feststellt, dass das Konzept gescheitert ist.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"beziehung","sensitive":false,"tags":["Humor","Beziehung"]},{"id":"joke-132","category":"Witz","title":"Beziehung","text":"Sie fragte, ob mir etwas aufgefallen sei. Ich wusste sofort: Die Prüfung hat begonnen.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"beziehung","sensitive":false,"tags":["Humor","Beziehung"]},{"id":"joke-133","category":"Witz","title":"Beziehung","text":"In Beziehungen gibt es zwei Arten von Menschen: die, die den Thermostat einstellen, und die, die ihn heimlich korrigieren.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"beziehung","sensitive":false,"tags":["Humor","Beziehung"]},{"id":"joke-134","category":"Witz","title":"Beziehung","text":"Wir haben dieselben Ziele. Nur völlig unterschiedliche Wege und Uhrzeiten.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"beziehung","sensitive":false,"tags":["Humor","Beziehung"]},{"id":"joke-135","category":"Witz","title":"Beziehung","text":"Romantik nach Jahren: „Ich hab dein Ladekabel mitgebracht.“","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"beziehung","sensitive":false,"tags":["Humor","Beziehung"]},{"id":"joke-136","category":"Witz","title":"Beziehung","text":"Ein gemeinsamer Einkauf zeigt, wie unterschiedlich zwei Menschen das Wort „nur“ verstehen.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"beziehung","sensitive":false,"tags":["Humor","Beziehung"]},{"id":"joke-137","category":"Witz","title":"Beziehung","text":"Liebe ist blind. Zusammenleben liefert anschließend die Sehhilfe.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"beziehung","sensitive":false,"tags":["Humor","Beziehung"]},{"id":"joke-138","category":"Witz","title":"Beziehung","text":"Der Satz „Ist mir egal“ hat in Beziehungen ungefähr zwölf Bedeutungen. Keine davon ist egal.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"beziehung","sensitive":false,"tags":["Humor","Beziehung"]},{"id":"joke-139","category":"Witz","title":"Arzt","text":"Der Arzt sagte, ich solle mich schonen. Ich wusste, dass irgendwann jemand meine Lebensphilosophie medizinisch bestätigt.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"arzt","sensitive":false,"tags":["Humor","Arzt"]},{"id":"joke-140","category":"Witz","title":"Arzt","text":"Im Wartezimmer altern Menschen nicht. Sie reifen.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"arzt","sensitive":false,"tags":["Humor","Arzt"]},{"id":"joke-141","category":"Witz","title":"Arzt","text":"Mein Arzt empfiehlt acht Stunden Schlaf. Mein Wecker hat Widerspruch eingelegt.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"arzt","sensitive":false,"tags":["Humor","Arzt"]},{"id":"joke-142","category":"Witz","title":"Arzt","text":"Der Arzt fragte nach meinem Stresslevel. Ich fragte, ob er eine Skala bis Montag hat.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"arzt","sensitive":false,"tags":["Humor","Arzt"]},{"id":"joke-143","category":"Witz","title":"Arzt","text":"Ich wollte beim Arzt nur ein Rezept. Bekommen habe ich Lebensberatung und einen Folgetermin.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"arzt","sensitive":false,"tags":["Humor","Arzt"]},{"id":"joke-144","category":"Witz","title":"Arzt","text":"Der Arzt sagte, Bewegung sei gesund. Ich bewege seitdem regelmäßig den Termin.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"arzt","sensitive":false,"tags":["Humor","Arzt"]},{"id":"joke-145","category":"Witz","title":"Arzt","text":"Blutdruck gemessen. Gerät funktioniert. Leider.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"arzt","sensitive":false,"tags":["Humor","Arzt"]},{"id":"joke-146","category":"Witz","title":"Arzt","text":"Beim Zahnarzt heißt „Sie spüren nur Druck“ offenbar etwas völlig anderes als im Alltag.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"arzt","sensitive":false,"tags":["Humor","Arzt"]},{"id":"joke-147","category":"Witz","title":"Arzt","text":"Der Arzt fragte, ob ich rauche. Ich sagte: „Nur wenn ich brenne.“ Das Formular war danach nicht einfacher.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"arzt","sensitive":false,"tags":["Humor","Arzt"]},{"id":"joke-148","category":"Witz","title":"Arzt","text":"Gesund leben ist einfach: Man darf nur fast alles nicht machen, was spontan Spaß macht.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"arzt","sensitive":false,"tags":["Humor","Arzt"]},{"id":"joke-149","category":"Witz","title":"Schwarz","text":"Ich möchte friedlich im Schlaf sterben wie mein Großvater. Nicht schreiend wie seine Mitfahrer. Ein Klassiker bleibt ein Klassiker.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"schwarz","sensitive":true,"tags":["Humor","Schwarz"]},{"id":"joke-150","category":"Witz","title":"Schwarz","text":"Mein letzter Wille: Bitte löscht meinen Browserverlauf. Würde und so.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"schwarz","sensitive":true,"tags":["Humor","Schwarz"]},{"id":"joke-151","category":"Witz","title":"Schwarz","text":"Der Tod kommt sicher. Wenigstens ein Termin ohne Warteschleife.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"schwarz","sensitive":true,"tags":["Humor","Schwarz"]},{"id":"joke-152","category":"Witz","title":"Schwarz","text":"Ich spare fürs Alter. Falls ich es nicht erreiche, war wenigstens die Inflation beschäftigt.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"schwarz","sensitive":true,"tags":["Humor","Schwarz"]},{"id":"joke-153","category":"Witz","title":"Schwarz","text":"Auf Beerdigungen merkt man, wie viele Menschen plötzlich sagen: „Wir müssen uns öfter sehen.“ Timing ist alles.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"schwarz","sensitive":true,"tags":["Humor","Schwarz"]},{"id":"joke-154","category":"Witz","title":"Schwarz","text":"Mein Lebensplan reicht bis Freitag. Danach übernimmt die Forschung.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"schwarz","sensitive":true,"tags":["Humor","Schwarz"]},{"id":"joke-155","category":"Witz","title":"Schwarz","text":"Unsterblichkeit klingt toll, bis man merkt, dass dann auch Montage unendlich oft vorkommen.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"schwarz","sensitive":true,"tags":["Humor","Schwarz"]},{"id":"joke-156","category":"Witz","title":"Schwarz","text":"Der Sensenmann hat wenigstens ein klares Aufgabenprofil.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"schwarz","sensitive":true,"tags":["Humor","Schwarz"]},{"id":"joke-157","category":"Witz","title":"Schwarz","text":"Wenn das Leben an mir vorbeizieht, hoffe ich, es hat wenigstens den Blinker gesetzt.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"schwarz","sensitive":true,"tags":["Humor","Schwarz"]},{"id":"joke-158","category":"Witz","title":"Schwarz","text":"Ich will nicht ewig leben. Ich möchte nur lange genug bleiben, um zu erfahren, wer meine ganzen Kabel braucht.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"schwarz","sensitive":true,"tags":["Humor","Schwarz"]},{"id":"joke-159","category":"Witz","title":"Erwachsen","text":"Erwachsensein ist, wenn ein leerer Wäschekorb kurz wie persönlicher Erfolg wirkt.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"erwachsen","sensitive":true,"tags":["Humor","Erwachsen"]},{"id":"joke-160","category":"Witz","title":"Erwachsen","text":"Früher waren Überraschungen spannend. Heute hoffe ich, dass auf der Rechnung keine stehen.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"erwachsen","sensitive":true,"tags":["Humor","Erwachsen"]},{"id":"joke-161","category":"Witz","title":"Erwachsen","text":"Luxus ist irgendwann nicht Champagner, sondern ein Termin, der abgesagt wird.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"erwachsen","sensitive":true,"tags":["Humor","Erwachsen"]},{"id":"joke-162","category":"Witz","title":"Erwachsen","text":"Meine Knie geben inzwischen Wetterberichte heraus, ohne meteorologische Ausbildung.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"erwachsen","sensitive":true,"tags":["Humor","Erwachsen"]},{"id":"joke-163","category":"Witz","title":"Erwachsen","text":"Ein freier Samstag ohne Verpflichtungen ist die erwachsene Version eines Freizeitparks.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"erwachsen","sensitive":true,"tags":["Humor","Erwachsen"]},{"id":"joke-164","category":"Witz","title":"Erwachsen","text":"Früher wollte ich nachts nicht schlafen. Heute würde ich gern, mein Rücken verhandelt nur noch.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"erwachsen","sensitive":true,"tags":["Humor","Erwachsen"]},{"id":"joke-165","category":"Witz","title":"Erwachsen","text":"Erwachsensein: Man besitzt fünf Ladekabel und nie das richtige.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"erwachsen","sensitive":true,"tags":["Humor","Erwachsen"]},{"id":"joke-166","category":"Witz","title":"Erwachsen","text":"Der Moment, in dem man freiwillig Vorratsdosen kauft, kommt ohne Vorwarnung.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"erwachsen","sensitive":true,"tags":["Humor","Erwachsen"]},{"id":"joke-167","category":"Witz","title":"Erwachsen","text":"Mit 20 war Ausschlafen bis Mittag Freiheit. Heute ist acht Uhr schon eine kleine Rebellion.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"erwachsen","sensitive":true,"tags":["Humor","Erwachsen"]},{"id":"joke-168","category":"Witz","title":"Erwachsen","text":"Meine Partybeleuchtung ist inzwischen die Lampe im Kühlschrank um 22 Uhr.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"erwachsen","sensitive":true,"tags":["Humor","Erwachsen"]},{"id":"joke-169","category":"Witz","title":"Derb","text":"Ich bin heute sozial voll ausgelastet. Zwei Menschen haben mit mir gesprochen.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"derb","sensitive":true,"tags":["Humor","Derb"]},{"id":"joke-170","category":"Witz","title":"Derb","text":"Es gibt Menschen, die bereichern jeden Raum. Besonders beim Verlassen.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"derb","sensitive":true,"tags":["Humor","Derb"]},{"id":"joke-171","category":"Witz","title":"Derb","text":"Ich habe nichts gegen dumme Fragen. Nur gegen die überraschend engagierte Serienproduktion.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"derb","sensitive":true,"tags":["Humor","Derb"]},{"id":"joke-172","category":"Witz","title":"Derb","text":"Mein Toleranzbereich ist heute geöffnet von 8:00 bis 8:03.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"derb","sensitive":true,"tags":["Humor","Derb"]},{"id":"joke-173","category":"Witz","title":"Derb","text":"Ich kann Kritik gut vertragen. Solange sie falsch ist und von jemand anderem handelt.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"derb","sensitive":true,"tags":["Humor","Derb"]},{"id":"joke-174","category":"Witz","title":"Derb","text":"Manche Diskussionen gewinnt man am besten, indem man nicht hingeht.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"derb","sensitive":true,"tags":["Humor","Derb"]},{"id":"joke-175","category":"Witz","title":"Derb","text":"Mein Gesicht kann leider keine automatischen Abwesenheitsnotizen senden.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"derb","sensitive":true,"tags":["Humor","Derb"]},{"id":"joke-176","category":"Witz","title":"Derb","text":"Ich bin nicht kompliziert. Die anderen sind nur erschreckend optimistisch.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"derb","sensitive":true,"tags":["Humor","Derb"]},{"id":"joke-177","category":"Witz","title":"Derb","text":"Heute ist ein guter Tag, um niemanden unnötig zu testen.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"derb","sensitive":true,"tags":["Humor","Derb"]},{"id":"joke-178","category":"Witz","title":"Derb","text":"Ich habe meine Meinung geändert. Die Menschen bleiben trotzdem anstrengend.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"derb","sensitive":true,"tags":["Humor","Derb"]},{"id":"joke-179","category":"Witz","title":"Kurz","text":"Anwesend. Begeisterung folgt separat.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"kurz","sensitive":false,"tags":["Humor","Kurz"]},{"id":"joke-180","category":"Witz","title":"Kurz","text":"Heute reicht funktional.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"kurz","sensitive":false,"tags":["Humor","Kurz"]},{"id":"joke-181","category":"Witz","title":"Kurz","text":"Kaffee zuerst. Persönlichkeit später.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"kurz","sensitive":false,"tags":["Humor","Kurz"]},{"id":"joke-182","category":"Witz","title":"Kurz","text":"Mittwoch zählt doppelt. Gefühlt.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"kurz","sensitive":false,"tags":["Humor","Kurz"]},{"id":"joke-183","category":"Witz","title":"Kurz","text":"Freitag in Sicht. Nicht erschrecken.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"kurz","sensitive":false,"tags":["Humor","Kurz"]},{"id":"joke-184","category":"Witz","title":"Kurz","text":"Ich laufe auf Restmotivation.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"kurz","sensitive":false,"tags":["Humor","Kurz"]},{"id":"joke-185","category":"Witz","title":"Kurz","text":"Plan läuft. Langsam, aber er läuft.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"kurz","sensitive":false,"tags":["Humor","Kurz"]},{"id":"joke-186","category":"Witz","title":"Kurz","text":"Keine Panik. Nur Montag.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"kurz","sensitive":false,"tags":["Humor","Kurz"]},{"id":"joke-187","category":"Witz","title":"Kurz","text":"Feierabend ist ein Ziel mit Uhrzeit.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"kurz","sensitive":false,"tags":["Humor","Kurz"]},{"id":"joke-188","category":"Witz","title":"Kurz","text":"Arbeitsmodus: technisch aktiv.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"kurz","sensitive":false,"tags":["Humor","Kurz"]},{"id":"motivation-021","category":"Motivation","title":"One More Day","text":"Wenn heute nur durchschnittlich wird, ist das völlig okay. Durchschnittliche Tage bringen einen genauso Richtung Wochenende.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"motivation-022","category":"Motivation","title":"One More Day","text":"Du musst dich nicht auf Arbeit freuen. Es genügt, wenn du dich später auf Feierabend freust.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"motivation-023","category":"Motivation","title":"One More Day","text":"Ein Haken hinter einem Tag ist manchmal mehr wert als zehn gute Vorsätze.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"motivation-024","category":"Motivation","title":"One More Day","text":"Der heutige Auftrag ist überschaubar: auftauchen, durchkommen, abhaken.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"motivation-025","category":"Motivation","title":"One More Day","text":"Nicht jeder Fortschritt fühlt sich nach Fortschritt an. Manchmal fühlt er sich einfach nach Mittwoch an.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"motivation-026","category":"Motivation","title":"One More Day","text":"Wenn der Kopf schon beim ganzen Monat streikt, gib ihm nur den heutigen Tag.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"motivation-027","category":"Motivation","title":"One More Day","text":"Ein erledigter Tag braucht im Nachhinein keine Motivation mehr.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"motivation-028","category":"Motivation","title":"One More Day","text":"Die Woche wird nicht auf einmal geschafft. Sie wird in einzelnen Tagen eingesammelt.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"motivation-029","category":"Motivation","title":"One More Day","text":"Auch 60 Prozent Energie können 100 Prozent Anwesenheit schaffen.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"motivation-030","category":"Motivation","title":"One More Day","text":"Der Start darf schwer sein. Er muss nur stattfinden.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"motivation-031","category":"Motivation","title":"One More Day","text":"Wenn heute zäh ist, darf heute zäh sein. Das Ziel bleibt trotzdem dasselbe.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"motivation-032","category":"Motivation","title":"One More Day","text":"Du arbeitest nicht für den Montag. Du arbeitest dich durch ihn hindurch.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"motivation-033","category":"Motivation","title":"One More Day","text":"Jeder Feierabend beginnt irgendwann mit einem Arbeitsbeginn. Leider hat das System diese Lücke nie geschlossen.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"motivation-034","category":"Motivation","title":"One More Day","text":"Nicht denken, wie lange noch. Erst einmal anfangen, dann darf die Uhr ihren Job machen.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"motivation-035","category":"Motivation","title":"One More Day","text":"Manchmal ist „ich bin trotzdem gegangen“ die beste Leistung des Tages.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"motivation-036","category":"Motivation","title":"One More Day","text":"Du brauchst heute keine Heldengeschichte. Ein grüner Haken reicht.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"motivation-037","category":"Motivation","title":"One More Day","text":"Ein Tag mehr geschafft ist kein Motivationsspruch, sondern Mathematik.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"motivation-038","category":"Motivation","title":"One More Day","text":"Wenn die Woche nervt, zerleg sie in Stücke. Heute ist nur eines davon.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"motivation-039","category":"Motivation","title":"One More Day","text":"Der morgige Tag bekommt seine Probleme morgen. Heute hat schon genug eigene.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"motivation-040","category":"Motivation","title":"One More Day","text":"Ein kleines Ziel, konsequent erreicht, schlägt ein großes Ziel, das nur hübsch klingt.","source":"Originaltext für One More Day","sourceUrl":null,"verified":true,"tone":"dry","sensitive":false,"tags":["Arbeit","Motivation"]},{"id":"mpk-001","category":"MPK · Hinter dem Song","title":"B.O.A.T.S. heißt wörtlich Programm","text":"B.O.A.T.S. steht für „Based On A True Story“. Michael Patrick Kelly erklärte, dass die Songs des Albums auf wahren Geschichten beruhen, die er selbst erlebt oder von anderen Menschen erfahren hat.","source":"GALA Interview","sourceUrl":"https://www.gala.de/stars/interview/michael-patrick-kelly--er-war--wie-ein-alter-laptop-mit-viren--22546196.html","verified":true,"tone":"fan","sensitive":false,"tags":["MPK","Hinter dem Song"]},{"id":"mpk-002","category":"MPK · Hinter dem Song","title":"60 fertige Songs, 15 ausgewählt","text":"Für B.O.A.T.S. schrieb Kelly nach eigener Aussage 60 vollständige Songs. Für die ursprüngliche Albumfassung wählte er daraus 15 aus.","source":"GALA Interview","sourceUrl":"https://www.gala.de/stars/interview/michael-patrick-kelly--er-war--wie-ein-alter-laptop-mit-viren--22546196.html","verified":true,"tone":"fan","sensitive":false,"tags":["MPK","Hinter dem Song"]},{"id":"mpk-003","category":"MPK · Hinter dem Song","title":"Vier Jahre Reifezeit","text":"Zwischen seinem vorherigen Album und B.O.A.T.S. lagen rund vier Jahre. Kelly wollte den Songs bewusst mehr Zeit zum Reifen geben, statt schnell das nächste Album nachzuschieben.","source":"GALA Interview","sourceUrl":"https://www.gala.de/stars/interview/michael-patrick-kelly--er-war--wie-ein-alter-laptop-mit-viren--22546196.html","verified":true,"tone":"fan","sensitive":false,"tags":["MPK","Hinter dem Song"]},{"id":"mpk-004","category":"MPK · Hinter dem Song","title":"Halbe Weltreise für Geschichten","text":"Für B.O.A.T.S. reiste Kelly unter anderem nach Grönland, auf die Färöer, nach Kenia, Kalifornien und in die Toskana, um Menschen und Geschichten zu finden, die ihn inspirieren konnten.","source":"urbanite Interview","sourceUrl":"https://www.urbanite.net/artikel/interview-michael-patrick-kelly/","verified":true,"tone":"fan","sensitive":false,"tags":["MPK","Hinter dem Song"]},{"id":"mpk-005","category":"MPK · Hinter dem Song","title":"Wahre Geschichten statt Fiktion","text":"Kelly sagte, wahre Geschichten hätten für ihn eine besondere Kraft. Diese Vorliebe für „based on a true story“ übertrug er bewusst auf das Albumkonzept.","source":"t-online / dpa","sourceUrl":"https://berlin.t-online.de/region/berlin/id_91112726/hit-melodien-mit-tiefgang-boats-von-michael-patrick-kelly.html","verified":true,"tone":"fan","sensitive":false,"tags":["MPK","Hinter dem Song"]},{"id":"mpk-006","category":"MPK · Hinter dem Song","title":"Mother's Day","text":"„Mother's Day“ ist Kellys früh verstorbener Mutter gewidmet. Er war fünf Jahre alt, als sie im Alter von 36 Jahren starb.","source":"Allgäuer Zeitung Interview","sourceUrl":"https://www.allgaeuer-zeitung.de/panorama/saenger-michael-patrick-kelly-ich-traeume-nachts-meine-songs-103492752","verified":true,"tone":"fan","sensitive":false,"tags":["MPK","Hinter dem Song"]},{"id":"mpk-007","category":"MPK · Hinter dem Song","title":"Perfektion bis zum Master","text":"Kelly berichtete, dass er selbst während des Mixings noch Teile neu aufnimmt, wenn ihn etwas stört. Vor Abgabe des B.O.A.T.S.-Masters arbeitete er bis in die letzte Nacht hinein.","source":"Allgäuer Zeitung Interview","sourceUrl":"https://www.allgaeuer-zeitung.de/panorama/saenger-michael-patrick-kelly-ich-traeume-nachts-meine-songs-103492752","verified":true,"tone":"fan","sensitive":false,"tags":["MPK","Hinter dem Song"]},{"id":"mpk-008","category":"MPK Moment","title":"Songideen kommen schnell, Songs nicht","text":"Kelly unterscheidet zwischen spontanen Songideen und fertigen Songs: Erste Ideen kämen oft schnell, an Text, Struktur und Produktion arbeite er dagegen lange.","source":"subtext.at Interview","sourceUrl":"https://www.subtext.at/2021/11/mpk-das-geschenk-des-lebens-ist-nicht-selbstverstaendlich/","verified":true,"tone":"fan","sensitive":false,"tags":["MPK","Hinter dem Song"]},{"id":"mpk-009","category":"MPK Moment","title":"Bewusst auf Stop gedrückt","text":"Nach Jahren des schnellen Musikgeschäfts nahm Kelly bewusst ein Sabbatjahr. Er wollte Zeit zum Reisen und Schreiben haben und ein Album schaffen, das nicht nur dem nächsten Veröffentlichungstermin hinterherläuft.","source":"subtext.at Interview","sourceUrl":"https://www.subtext.at/2021/11/mpk-das-geschenk-des-lebens-ist-nicht-selbstverstaendlich/","verified":true,"tone":"fan","sensitive":false,"tags":["MPK","Hinter dem Song"]},{"id":"mpk-010","category":"MPK Moment","title":"Songs bekommen ein Eigenleben","text":"Kelly bezeichnete es als besonderen Erfolg, wenn Menschen seine Songs mit eigenen wichtigen Lebensmomenten verbinden, etwa Wettkämpfen, Hochzeiten, Abschieden oder Trost.","source":"MoPop Interview","sourceUrl":"https://mopop.de/interviews/michael-patrick-kelly-leute-haben-zu-meinen-songs-kinder-gezeugt-19655","verified":true,"tone":"fan","sensitive":false,"tags":["MPK","Hinter dem Song"]},{"id":"mpk-011","category":"MPK Moment","title":"Shake Away als mentale Hilfe","text":"Kelly erzählte von der Skirennfahrerin Michelle Gisin, die seine Musik vor Wettkämpfen nutzte, um Ängste und Sorgen abzuschütteln; er nannte „Shake Away“ als passenden Song dazu.","source":"MoPop Interview","sourceUrl":"https://mopop.de/interviews/michael-patrick-kelly-leute-haben-zu-meinen-songs-kinder-gezeugt-19655","verified":true,"tone":"fan","sensitive":false,"tags":["MPK","Hinter dem Song"]},{"id":"mpk-012","category":"MPK Moment","title":"Musik als gemeinsames Erlebnis","text":"Kelly beschreibt Konzerte als Momente, in denen Menschen Alltagssorgen für einige Stunden loslassen, gemeinsam tanzen, singen, lachen oder weinen können.","source":"urbanite Interview","sourceUrl":"https://www.urbanite.net/artikel/interview-michael-patrick-kelly/","verified":true,"tone":"fan","sensitive":false,"tags":["MPK","Hinter dem Song"]},{"id":"mpk-013","category":"MPK · Hinter dem Song","title":"Der Titelsong B.O.A.T.S.","text":"Beim Titelsong geht es laut Kelly auch um die Frage, wo Menschen ihre eigene Geschichte beschönigen, Muster verdrängen oder sich selbst ein falsches Bild erzählen.","source":"Süddeutsche Zeitung Interview","sourceUrl":"https://www.sueddeutsche.de/muenchen/michael-patrick-kelly-paddy-kelly-kelly-family-olympiahalle-muenchen-1.5653295","verified":true,"tone":"fan","sensitive":false,"tags":["MPK","Hinter dem Song"]},{"id":"mpk-014","category":"MPK Moment","title":"Drei Akkorde und Wahrheit","text":"Für B.O.A.T.S. griff Kelly wiederholt das Songwriter-Motto auf, ein guter Song brauche im Kern wenige Akkorde und Wahrheit. Für ihn war die Wahrhaftigkeit der Geschichten das verbindende Element des Albums.","source":"GALA / t-online Interviews","sourceUrl":"https://www.gala.de/stars/interview/michael-patrick-kelly--er-war--wie-ein-alter-laptop-mit-viren--22546196.html","verified":true,"tone":"fan","sensitive":false,"tags":["MPK","Hinter dem Song"]},{"id":"mpk-015","category":"MPK Moment","title":"60 aus Hunderten Ideen","text":"Kelly berichtete von hunderten Songideen, aus denen schließlich 60 vollständige Songs entstanden. Nur ein Teil davon schaffte es auf B.O.A.T.S.","source":"subtext.at Interview","sourceUrl":"https://www.subtext.at/2021/11/mpk-das-geschenk-des-lebens-ist-nicht-selbstverstaendlich/","verified":true,"tone":"fan","sensitive":false,"tags":["MPK","Hinter dem Song"]},{"id":"joey-001","category":"Joey Impuls","title":"Das Ziel kommt vor der Motivation","text":"Joey Kelly hält das konkrete Ziel für wichtiger als das Gefühl von Motivation. Ist das Ziel entschieden, entstehen für ihn daraus Motivation, Disziplin und Ausdauer.","source":"Handwerk Magazin Interview","sourceUrl":"https://www.handwerk-magazin.de/interview-mit-joey-kelly-wer-ziele-hat-ist-motiviert-182659/","verified":true,"tone":"fan","sensitive":false,"tags":["Joey","Motivation"]},{"id":"joey-002","category":"Joey Impuls","title":"Ein Termin macht das Ziel konkret","text":"Bei Zielen betont Joey Kelly nicht nur das Was, sondern auch einen klaren Termin. Ein Ziel ohne zeitlichen Rahmen bleibt leichter unverbindlich.","source":"Handwerk Magazin Interview","sourceUrl":"https://www.handwerk-magazin.de/interview-mit-joey-kelly-wer-ziele-hat-ist-motiviert-182659/","verified":true,"tone":"fan","sensitive":false,"tags":["Joey","Motivation"]},{"id":"joey-003","category":"Joey Impuls","title":"Disziplin statt Tagesform","text":"In Joey Kellys Verständnis folgt auf ein gesetztes Ziel nicht tägliche Begeisterung, sondern diszipliniertes und ausdauerndes Verfolgen des Vorhabens.","source":"Handwerk Magazin Interview","sourceUrl":"https://www.handwerk-magazin.de/interview-mit-joey-kelly-wer-ziele-hat-ist-motiviert-182659/","verified":true,"tone":"fan","sensitive":false,"tags":["Joey","Motivation"]},{"id":"history-001","category":"Kuriose Geschichte","title":"Ein Schloss spart am falschen Ende","text":"Beim Bau des Smithsonian Castle wurden aus Kostengründen geplante feuerfeste Konstruktionen teilweise durch Holz ersetzt. 1850 sackte während der Bauarbeiten ein großer Teil der Innenkonstruktion in den Keller.","source":"Smithsonian Institution Archives","sourceUrl":"https://siarchives.si.edu/blog/smithsonian-castle-mystery","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte"]},{"id":"history-002","category":"Kuriose Geschichte","title":"Das Smithsonian Castle brannte später wirklich","text":"1865 zerstörte ein Brand große Teile des oberen Smithsonian Castle. Das Feuer vernichtete unter anderem Räume und Sammlungsbestandteile. Sparen an Brandsicherheit besitzt rückblickend einen gewissen bitteren Humor.","source":"Smithsonian Institution Archives","sourceUrl":"https://siarchives.si.edu/blog/smithsonian-castle-mystery","verified":true,"tone":"dark","sensitive":true,"tags":["Geschichte"]},{"id":"history-003","category":"Historisches Rätsel","title":"Das verschwundene Bernsteinzimmer","text":"Das berühmte Bernsteinzimmer wurde im Zweiten Weltkrieg von deutschen Truppen demontiert und abtransportiert. Sein endgültiges Schicksal nach Kriegsende ist bis heute nicht zweifelsfrei geklärt.","source":"Smithsonian Magazine","sourceUrl":"https://www.smithsonianmag.com/history/a-brief-history-of-the-amber-room-160940121/","verified":true,"tone":"mystery","sensitive":false,"tags":["Mystery"]},{"id":"history-004","category":"Kuriose Geschichte","title":"Orient-Express: mehr als Luxuszug","text":"Der Orient-Express wurde nicht nur zum Symbol luxuriösen Reisens. Seine Geschichte ist auch mit Diplomatie, Spionage, Krieg und politischen Umbrüchen verbunden.","source":"Smithsonian Magazine","sourceUrl":"https://www.smithsonianmag.com/history/a-brief-history-of-the-orient-express-149702768/","verified":true,"tone":"curious","sensitive":false,"tags":["Geschichte"]},{"id":"history-005","category":"Kuriose Geschichte","title":"Katzen leben lange mit uns","text":"Archäologische und genetische Forschung deutet darauf hin, dass Katzen seit Tausenden Jahren in enger Nähe zu Menschen leben, ohne denselben Domestikationsweg wie Hunde genommen zu haben.","source":"Smithsonian Magazine","sourceUrl":"https://www.smithsonianmag.com/history/a-brief-history-of-house-cats-158390681/","verified":true,"tone":"curious","sensitive":false,"tags":["Tiere","Geschichte"]},{"id":"antike-001","category":"Geschichte · Antike","title":"Woher das Wort Demokratie kommt","text":"Das griechische dēmokratia verbindet dēmos, das Bürger- beziehungsweise Volkskörper bezeichnet, mit kratos, Herrschaft oder Macht. Wörtlich steckt also die Herrschaft des Volkes im Begriff.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/collection/71/government--society-in-ancient-greece/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-002","category":"Geschichte · Antike","title":"Athens Demokratie war direkt","text":"Im klassischen Athen entschieden Bürger nicht nur, wer sie vertreten sollte. Sie konnten selbst in der Volksversammlung sprechen und über Sachfragen abstimmen.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/article/1165/ancient-greek-inventions/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-003","category":"Geschichte · Antike","title":"Aber längst nicht alle durften mitmachen","text":"Die berühmte athenische Demokratie war nach heutigem Maßstab stark eingeschränkt: Politische Bürgerrechte hatten freie erwachsene männliche Bürger. Frauen, Sklaven und viele Zugewanderte waren ausgeschlossen.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/article/1165/ancient-greek-inventions/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-004","category":"Geschichte · Antike","title":"Mehrheit per Handzeichen","text":"In der athenischen Volksversammlung wurden Entscheidungen häufig durch Handzeichen getroffen. Eine einfache Mehrheit entschied.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/article/1165/ancient-greek-inventions/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-005","category":"Geschichte · Antike","title":"Platz für ungefähr 6.000","text":"Der Versammlungsort der Athener konnte ungefähr 6.000 Bürger aufnehmen. Bei besonders wichtigen Fragen war entsprechend viel Betrieb.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/article/1165/ancient-greek-inventions/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-006","category":"Geschichte · Antike","title":"Politik war Bürgerpflicht","text":"Athenische Bürger konnten nicht nur abstimmen. Von ihnen wurde auch erwartet, zeitweise Ämter oder andere öffentliche Aufgaben zu übernehmen.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/article/1165/ancient-greek-inventions/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-007","category":"Geschichte · Antike","title":"Los statt Wahl","text":"Viele öffentliche Aufgaben in Athen wurden per Los vergeben. Dahinter stand die Idee, politische Beteiligung nicht dauerhaft einer kleinen Berufspolitiker-Schicht zu überlassen.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/article/1165/ancient-greek-inventions/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-008","category":"Geschichte · Antike","title":"Eine Maschine loste Geschworene aus","text":"Das Kleroterion war eine Losmaschine, mit der Athen unter anderem Geschworene zufällig auswählte. Zufall sollte Manipulation und vorherige Bestechung erschweren.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/article/1165/ancient-greek-inventions/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-009","category":"Geschichte · Antike","title":"Riesige Geschworenengerichte","text":"Athenische Gerichte konnten aus sehr vielen Bürgern bestehen. Das unterschied sich deutlich von modernen zwölfköpfigen Jurys.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/article/1165/ancient-greek-inventions/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-010","category":"Geschichte · Antike","title":"Politisches Exil per Abstimmung","text":"Beim Ostrakismos konnten Athener darüber abstimmen, einen als gefährlich angesehenen Bürger für Jahre aus der Stadt zu verbannen. Daher stammt unser Wort Ostrakismus.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/collection/71/government--society-in-ancient-greece/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-011","category":"Geschichte · Antike","title":"Agora: Marktplatz und Nachrichtenfeed","text":"Die Agora war nicht bloß Einkaufsplatz. Sie war ein zentraler sozialer und politischer Treffpunkt, an dem Handel, Gespräche und öffentliche Angelegenheiten zusammenliefen.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/collection/76/daily-life-in-ancient-greece/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-012","category":"Geschichte · Antike","title":"Symposium war mehr als Trinken","text":"Bei einem griechischen Symposium wurde getrunken, aber auch musiziert, Gedichte vorgetragen, diskutiert und über Politik oder Alltagsfragen gesprochen.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/collection/76/daily-life-in-ancient-greece/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-013","category":"Geschichte · Antike","title":"Griechische Nachbarn konnten sehr verschieden sein","text":"Das antike Griechenland war kein einheitlicher Nationalstaat wie das heutige Griechenland, sondern bestand aus zahlreichen Poleis mit eigenen politischen Systemen und Interessen.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/collection/71/government--society-in-ancient-greece/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-014","category":"Geschichte · Antike","title":"Demokratie war nicht überall griechisch","text":"Neben Demokratien existierten in griechischen Stadtstaaten auch Oligarchien, Monarchien und andere Herrschaftsformen.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/collection/71/government--society-in-ancient-greece/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-015","category":"Geschichte · Antike","title":"Sport und Politik lagen nah beieinander","text":"Öffentliche Wettkämpfe, religiöse Feste und Politik waren in der griechischen Polis eng mit dem Gemeinschaftsleben verbunden.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/collection/76/daily-life-in-ancient-greece/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-016","category":"Geschichte · Antike","title":"Die Griechen bauten kilometerlange Tunnel","text":"Griechische Ingenieure bauten bereits im 6. Jahrhundert v. Chr. auf Samos einen ungefähr einen Kilometer langen Tunnel zur Wasserversorgung.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/article/1165/ancient-greek-inventions/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-017","category":"Geschichte · Antike","title":"Krane halfen beim Tempelbau","text":"Flaschenzüge, Winden und Krane ermöglichten griechischen Baumeistern, schwere Steinblöcke für Tempel und Befestigungen zu bewegen.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/article/1165/ancient-greek-inventions/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-018","category":"Geschichte · Antike","title":"Aquädukte waren nicht nur römisch","text":"Auch Griechen bauten Wasserleitungen und Aquädukte. Die Römer machten diese Technik später besonders berühmt und entwickelten sie in enormem Maßstab weiter.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/article/1165/ancient-greek-inventions/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-019","category":"Geschichte · Antike","title":"Geometrie wurde zur Beweisdisziplin","text":"Griechische Mathematiker machten systematische Beweise und logische Herleitungen zu einem zentralen Bestandteil mathematischen Denkens.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/article/1165/ancient-greek-inventions/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-020","category":"Geschichte · Antike","title":"Medizin löste sich teilweise von Magie","text":"Griechische medizinische Traditionen versuchten Krankheiten zunehmend durch Beobachtung natürlicher Ursachen zu erklären, auch wenn Religion und Medizin weiterhin nebeneinander existierten.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/article/1165/ancient-greek-inventions/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-021","category":"Geschichte · Rom","title":"Rom war fast 500 Jahre Republik","text":"Traditionell wird die römische Republik von 509 bis 27 v. Chr. datiert. Danach begann mit Augustus die Kaiserzeit.","source":"Metropolitan Museum of Art","sourceUrl":"https://www.metmuseum.org/-/media/files/learn/for-educators/publications-for-educators/roman.pdf","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-022","category":"Geschichte · Rom","title":"Zwei Konsuln statt eines Königs","text":"An der Spitze der Republik standen gewöhnlich zwei jährlich gewählte Konsuln. Die Aufteilung sollte verhindern, dass die höchste reguläre Macht dauerhaft bei nur einer Person lag.","source":"Metropolitan Museum of Art","sourceUrl":"https://www.metmuseum.org/-/media/files/learn/for-educators/publications-for-educators/roman.pdf","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-023","category":"Geschichte · Rom","title":"SPQR ist kein Fantasiecode","text":"SPQR steht für Senatus Populusque Romanus: Senat und römisches Volk. Die Buchstaben erschienen unter anderem auf militärischen Standarten und sind bis heute mit Rom verbunden.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/collection/49/government-in-ancient-rome/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-024","category":"Geschichte · Rom","title":"Rom war demokratisch und oligarchisch zugleich","text":"Römische Bürger konnten in Versammlungen Gesetze beschließen, doch der aristokratisch geprägte Senat besaß enormen Einfluss. Die Republik war deshalb keine moderne Demokratie.","source":"Metropolitan Museum of Art","sourceUrl":"https://www.metmuseum.org/-/media/files/learn/for-educators/publications-for-educators/roman.pdf","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-025","category":"Geschichte · Rom","title":"Senatoren waren leicht zu erkennen","text":"Römische Senatoren demonstrierten ihren Rang unter anderem mit besonderen Kleidungsmerkmalen, Ringen und Schuhen. Statussymbole sind also wirklich keine Erfindung von LinkedIn.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/collection/49/government-in-ancient-rome/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-026","category":"Geschichte · Rom","title":"Römischer Beton war ein Gamechanger","text":"Die Römer erfanden Beton nicht, nutzten ihn aber ab dem späten republikanischen Zeitalter besonders innovativ. Vulkanisches Material wie Pozzolan half bei widerstandsfähigem Mörtel.","source":"Metropolitan Museum of Art","sourceUrl":"https://www.metmuseum.org/-/media/files/learn/for-educators/publications-for-educators/roman.pdf","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-027","category":"Geschichte · Rom","title":"Beton ermöglichte riesige Innenräume","text":"Mit römischem Beton konnten Gewölbe und Kuppeln gebaut werden, ohne überall massive Steinblöcke oder Säulenreihen zu benötigen.","source":"Metropolitan Museum of Art","sourceUrl":"https://www.metmuseum.org/-/media/files/learn/for-educators/publications-for-educators/roman.pdf","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-028","category":"Geschichte · Rom","title":"Triumphbögen waren politische Medien","text":"Triumphbögen feierten militärische und politische Erfolge mit Architektur und Reliefbildern. Monumentale Öffentlichkeitsarbeit gab es lange vor Plakatwänden.","source":"Metropolitan Museum of Art","sourceUrl":"https://www.metmuseum.org/-/media/files/learn/for-educators/publications-for-educators/roman.pdf","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-029","category":"Geschichte · Rom","title":"Thermen waren soziale Netzwerke","text":"Römische Bäder dienten nicht nur der Körperpflege. Sie waren Orte für Sport, Gespräche, Geschäftskontakte, Entspannung und Klatsch.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/collection/48/daily-life-in-ancient-rome/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-030","category":"Geschichte · Rom","title":"Wagenrennen hatten Fangruppen","text":"Römische Wagenrennen besaßen farblich gekennzeichnete Rennställe beziehungsweise Parteien. Anhänger konnten ihre Teams leidenschaftlich und gelegentlich gewalttätig unterstützen.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/collection/48/daily-life-in-ancient-rome/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-031","category":"Geschichte · Rom","title":"Wagenlenker konnten reich werden","text":"Erfolgreiche Wagenlenker konnten durch Preisgelder enorme Summen verdienen und zu gefeierten Publikumslieblingen werden.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/collection/48/daily-life-in-ancient-rome/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-032","category":"Geschichte · Rom","title":"Saturnalien stellten Regeln auf den Kopf","text":"Während der Saturnalien gehörten Rollentausch, ausgelassene Feiern und gelockerte gesellschaftliche Regeln zum Fest. Rom hatte also eine offiziell genehmigte Phase kontrollierten Chaos.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/collection/48/daily-life-in-ancient-rome/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-033","category":"Geschichte · Rom","title":"Brot und Spiele hatte politische Bedeutung","text":"Öffentliche Unterhaltung und Versorgung spielten eine wichtige Rolle im Verhältnis zwischen Herrschenden und Bevölkerung. Spiele waren deshalb weit mehr als bloßer Zeitvertreib.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/collection/48/daily-life-in-ancient-rome/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-034","category":"Geschichte · Rom","title":"Gladiatoren waren nicht jeden Tag dran","text":"Gladiatorenkämpfe waren besondere Veranstaltungen, nicht die tägliche Standardbeschäftigung jedes Römers. Theater, Wagenrennen, Bäder und religiöse Feste gehörten ebenso zur Unterhaltung.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/collection/48/daily-life-in-ancient-rome/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-035","category":"Geschichte · Rom","title":"Die Republik hatte viele Ämter","text":"Neben den Konsuln existierten zahlreiche weitere Magistrate, darunter Prätoren, Quästoren und Ädilen, mit unterschiedlichen Verwaltungs- und Rechtsaufgaben.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/collection/49/government-in-ancient-rome/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-036","category":"Geschichte · Rom","title":"Zwölftafelgesetz als frühe Rechtsbasis","text":"Die Zwölftafeln aus dem 5. Jahrhundert v. Chr. gehörten zu den grundlegenden schriftlich fixierten Rechtsquellen Roms.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/collection/49/government-in-ancient-rome/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-037","category":"Geschichte · Rom","title":"Augustus behielt republikanische Kulissen","text":"Augustus stellte seine Herrschaft offiziell als Wiederherstellung der Republik dar, konzentrierte tatsächlich aber entscheidende Macht bei sich. Politik verstand schon damals Branding.","source":"Metropolitan Museum of Art","sourceUrl":"https://www.metmuseum.org/-/media/files/learn/for-educators/publications-for-educators/roman.pdf","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-038","category":"Geschichte · Rom","title":"Kaiserbilder waren Propaganda","text":"Porträts der Kaiser auf Statuen, Münzen und anderen Medien verbreiteten ein kontrolliertes öffentliches Herrscherbild im ganzen Reich.","source":"Metropolitan Museum of Art","sourceUrl":"https://www.metmuseum.org/de/essays/the-julio-claudian-dynasty-27-b-c-68-a-d","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-039","category":"Geschichte · Rom","title":"Claudius baute Infrastruktur","text":"Unter Kaiser Claudius wurden große öffentliche Bauprojekte vorangetrieben, darunter Aquädukte, Kanäle und der Ausbau des Hafens von Ostia.","source":"Metropolitan Museum of Art","sourceUrl":"https://www.metmuseum.org/de/essays/the-julio-claudian-dynasty-27-b-c-68-a-d","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"antike-040","category":"Geschichte · Rom","title":"Römische Freizeit begann teils früh","text":"Für manche wohlhabende Römer konzentrierten sich Geschäfte auf den Vormittag; der Nachmittag konnte Bädern, Spielen oder anderen Freizeitaktivitäten gehören.","source":"World History Encyclopedia","sourceUrl":"https://www.worldhistory.org/article/637/roman-daily-life/","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"history-006","category":"Geschichte · Ägypten","title":"Hieroglyphen waren nicht einfach Bilder","text":"Ägyptische Hieroglyphen konnten Laute, ganze Wörter oder Bedeutungszusätze darstellen. Das Schriftsystem war erheblich komplexer als eine Sammlung kleiner Bildchen.","source":"Smithsonian Institution","sourceUrl":"https://www.si.edu/spotlight/ancient-egypt","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"history-007","category":"Geschichte · Ägypten","title":"Mumifizierung war religiös geprägt","text":"Die Erhaltung des Körpers hing mit altägyptischen Vorstellungen vom Tod und Weiterleben zusammen. Mumifizierung war deshalb Teil eines größeren religiösen Systems.","source":"British Museum","sourceUrl":"https://www.britishmuseum.org/collection/galleries/egyptian-death-and-afterlife-mummies","verified":true,"tone":"historical","sensitive":false,"tags":[]},{"id":"history-008","category":"Geschichte · Ägypten","title":"Nicht nur Pharaonen wurden mumifiziert","text":"Mumifizierung war keineswegs ausschließlich Herrschern vorbehalten. Je nach Epoche und sozialem Status wurden auch andere Menschen und sogar Tiere mumifiziert.","source":"British Museum","sourceUrl":"https://www.britishmuseum.org/collection/galleries/egyptian-death-and-afterlife-mummies","verified":true,"tone":"historical","sensitive":false,"tags":[]}]};
